programs.sol:
"""A lexical approximation of quantity/duration and institutional complements.

Strong positive cases are 'of' after institution names or collection/quantity
nouns, counted long durations, and distance units. Clock-time markers are
mostly negative. The constants are coarse averages fitted on training text.
Institutional 'for'/'on' phrases are included too. Word families share
predictions, deliberately omitting many lexical details.
Only the latest 60 characters are retained, resetting at document boundaries.
"""
import re

READS = ()
INSTITUTIONS = set('university institute department museum college school'.split())
OTHER_INSTITUTIONS = set('academy ministry council bureau faculty court board house '
                   'office society library gallery journal league'.split())
COLLECTIVE_NOUNS = set('set list group series collection range variety array '
                      'family bunch chain circle suite'.split())
CLASS_NOUNS = set('type kind sort class category form species'.split())
QUANTITY_NOUNS = set('number amount quantity degree level plurality sum unit'.split())
CONTAINERS = set('cup bag bowl box basket pack pile stack'.split())
SPATIAL_NOUNS = set('center centre field line area region state city province'.split())
PARTITIVES = set('all half two member participant'.split())
DIRECTIONS = set('west east north south outside top middle'.split())
NUMBER_WORDS = set('one two three four five six seven eight nine ten eleven twelve '
                   'thirteen fourteen fifteen sixteen seventeen eighteen nineteen '
                   'twenty thirty forty fifty sixty seventy eighty ninety hundred '
                   'thousand million'.split())

# Each pair gives the uncounted and counted readings of a duration unit.
DURATIONS = {
    'years': (0.50, 1.40), 'months': (0.40, 1.28),
    'weeks': (0.70, 1.48), 'days': (0.30, 0.86),
    'hours': (0.10, 0.34), 'minutes': (0.00, 0.15),
    'seconds': (0.30, 0.56), 'year': (-0.08, 0.84),
    'month': (-0.04, 0.66), 'week': (0.02, 0.60),
    'day': (-0.07, 0.06), 'hour': (-0.35, -0.23),
    'minute': (-0.50, -0.48), 'second': (-0.04, -0.04),
    'decade': (0.66, 0.80), 'decades': (0.85, 1.40),
    'century': (0.62, 0.70), 'centuries': (0.75, 1.15),
    'season': (0.22, 0.30), 'seasons': (0.28, 0.45),
    'generations': (0.40, 0.55), 'nights': (0.35, 0.45),
}
MEASUREMENTS = {
    'miles': 0.52, 'inches': 0.50, 'feet': 0.17,
    'kilometers': 0.48, 'kilometres': 0.49, 'meters': 0.23,
    'metres': 0.40, 'mile': 0.24, 'inch': 0.27,
}
CLOCK_WORDS = {'morning': -0.55, 'afternoon': -0.54, 'evening': -0.27,
               'utc': -0.42, 'uhr': -0.95, 'min': -0.19, 'mins': -0.85}


def of_complement(previous, title):
    singular = previous
    if previous.endswith('ies'):
        singular = previous[:-3] + 'y'
    elif previous.endswith('s') and previous not in {'class', 'species', 'series'}:
        singular = previous[:-1]
    if singular in INSTITUTIONS:
        return 0.95 + 0.55 * title
    if singular in OTHER_INSTITUTIONS:
        return 0.68 + 0.45 * title
    if previous in {'piece', 'pieces'}:
        return 1.05
    if previous in {'pair', 'pairs', 'amount', 'amounts'}:
        return 0.80
    if previous == 'set':
        return 0.98
    if previous in COLLECTIVE_NOUNS or singular in COLLECTIVE_NOUNS:
        return 0.80 if previous == singular else 0.65
    if previous in CLASS_NOUNS or singular in CLASS_NOUNS:
        value = 0.35 if singular in {'kind', 'sort', 'species'} else 0.61
        return value + (0.27 if previous != singular else 0.0)
    if previous in QUANTITY_NOUNS or singular in QUANTITY_NOUNS:
        return 0.59
    if previous in CONTAINERS or singular in CONTAINERS:
        return 0.54
    if previous in SPATIAL_NOUNS or singular in SPATIAL_NOUNS:
        return 0.51
    if previous in {'years', 'months', 'weeks', 'decades', 'centuries'}:
        return 0.67
    if previous in {'source', 'sources', 'sequence', 'sequences'}:
        return 0.70
    if previous in PARTITIVES or previous in DIRECTIONS:
        return -0.25
    return 0.015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    match = re.search(r'([A-Za-z]+)\s*$', before.replace('\\n', '\n'))
    previous = match.group(1).lower() if match else ''
    title = bool(match and match.group(1)[0].isupper())
    numeric = bool(re.search(r'\d[\d,.½¼¾]*\s*$', before))
    counted = numeric or previous in NUMBER_WORDS
    boundary = (token[:1].isspace() or token.startswith('-')
                or not before[-1:].isalnum())
    value = 0.0
    if word == 'of':
        value = of_complement(previous, title)
    elif word == 'for' and previous in {'institute', 'center', 'centers', 'centre', 'society'}:
        value = 0.85 if title else 0.30
        if previous == 'institute' and title:
            value = 1.20
    elif word == 'on' and previous in {'committee', 'council', 'commission', 'conference'}:
        value = 0.65 if title else 0.28
    elif boundary and word in DURATIONS:
        low, high = DURATIONS[word]
        specificity = 1.0 if counted else 0.0
        if previous in {'few', 'several', 'couple', 'half'}:
            specificity = 0.70
        elif previous == 'many':
            specificity = 0.30
        value = low + specificity * (high - low)
        if word in {'year', 'month', 'week'}:
            if previous in {'a', 'per', 'every', 'each'}:
                value = 0.28
            elif previous in {'last', 'next', 'previous'}:
                value = 0.35 if word == 'year' else 0.12
            elif previous in {'this', 'the', 'that', 'same'}:
                value = -0.22
            if token.startswith('-'):
                value = 0.90
        elif word == 'day' and previous in {'last', 'next', 'previous', 'following'}:
            value = -0.32
        elif word == 'minute' and previous == 'last':
            value = -0.95
    elif boundary and word in MEASUREMENTS:
        value = MEASUREMENTS[word]
    elif word in {'am', 'pm'} and (counted or word == 'pm'):
        value = -0.80 if token[:1].isspace() else -0.48
    elif word == '.m' and previous in {'a', 'p'}:
        value = -0.40
    elif boundary and word in CLOCK_WORDS:
        value = CLOCK_WORDS[word]
    elif word == '年':
        value = 0.55 if counted else 0.22
    elif word in {'日', '일', '點', '点', '点半'}:
        value = -0.65 if counted else -0.15
    elif word in {'時', '时', '分', '시'}:
        value = -0.28
    elif boundary and word in {'jahre', 'jahren', 'jahr', 'años', 'anos',
                               'года', 'году', 'лет', 'meses'}:
        value = 0.52 if counted else 0.25
    elif word in {'년', '岁', '岁的', '周年', '世纪', '年的', '年に', '十年'}:
        value = 0.45 if counted else 0.25
    elif word in {'上午', '下午'}:
        value = -0.55
    elif word in {'日上午', '日下午', '日晚'}:
        value = -1.10
    return (doc, (before + token)[-60:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1986 -- fires on the word "of" in a few kinds of phrase, and on
time-span nouns after a number.

Predicts the component's activation at each token from the words just before it:

1. "of" after a classifier or collection noun ("number of", "set of", "type of", "range of",
   "piece of", "list of"): the phrase names a kind, an amount or a group. About 0.65.
2. "of" inside an organisation's name ("University of", "Department of", "Court of",
   "Council of"), looking back a few words so "School of" after "University" counts. About 1.05.
3. Duration nouns after a number, or after a hyphenated number ("five years", "two weeks",
   "20-year"). About 0.95.
4. "年" (year) about 0.5; "日" (day) and "AM"/"PM" about -0.75.

Every other "of" ("member of", "one of", "all of", "result of") and every other token predicts 0.
"""

CLASSIFIER_NOUNS = {
    "number", "amount", "set", "range", "piece", "list", "type", "types", "form", "forms", "variety",
    "array", "group", "groups", "sequence", "level", "levels", "series", "class", "classes",
    "collection", "kind", "kinds", "sum", "sort", "bag", "source", "pair", "pairs", "degree",
    "period", "center", "centre", "snippet", "sheet", "field", "line", "mix", "mixture",
    "categories", "quantity", "unit", "units", "plurality", "system", "area", "segment", "circle",
    "sense", "branch", "ways",
}
ORGANISATION_NOUNS = {
    "University", "Department", "School", "Institute", "College", "Museum", "Court", "Board",
    "Society", "Council", "Ministry", "Bureau", "Office", "Library", "Academy", "Kingdom",
    "House", "Cathedral", "District", "Republic", "Committee", "Association", "Commission",
}
DURATION_NOUNS = {
    " year", " years", " month", " months", " week", " weeks", " day", " days", " decade",
    " decades", " century", " centuries", " hour", " hours", " minute", " minutes", " mile", " miles",
    "-year", "-years", "-month", "-months", "-week", "-weeks", "-day", "-days",
}
NUMBER_WORDS = {
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven",
    "twelve", "twenty", "thirty", "forty", "fifty", "hundred", "thousand", "several", "few", "many",
}
READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    # the words just before this token in the same document, nearest first
    back = []
    for i in range(2, min(len(prefix), 6) + 1):
        if prefix.document_ids[-i] != prefix.document_ids[-1]:
            break
        back.append(prefix.token_strings[-i].strip())
    if tok == " of":
        if back and back[0].lower() in CLASSIFIER_NOUNS:
            return carry, 0.65
        if any(word in ORGANISATION_NOUNS for word in back):
            return carry, 1.05
        return carry, 0.0
    if tok in DURATION_NOUNS:
        prev = back[0] if back else ""
        if prev.isdigit() or prev.lower() in NUMBER_WORDS or tok.startswith("-"):
            return carry, 0.95
        return carry, 0.0
    if tok == "年":
        return carry, 0.5
    if tok == "日":
        return carry, -0.75
    if tok in (" AM", " PM"):
        return carry, -0.75
    return carry, 0.0

programs.luna:
"""Predict a small 'of' response and flag quantified time and measure words."""
READS = ()

TIME_UNITS = {
    "year", "years", "month", "months", "week", "weeks", "day", "days",
    "hour", "hours", "minute", "minutes", "second", "seconds",
}
MEASURE_UNITS = {
    "inch", "inches", "mile", "miles", "foot", "feet", "cm", "mm", "km",
    "meter", "meters", "metre", "metres", "kg", "lb", "lbs",
}
NUMBER_WORDS = {
    "a", "an", "one", "two", "three", "four", "five", "six", "seven",
    "eight", "nine", "ten", "hundred", "thousand", "few", "several",
    "couple", "dozen",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = list(carry[1]) if carry is not None and carry[0] == doc else []
    word = prefix.token_strings[-1].strip().lower().strip(".,()[];:!?")
    number_nearby = any(
        token.strip().lower().strip(".,()[]-–") in NUMBER_WORDS
        or any(char.isdigit() for char in token)
        for token in recent[-3:]
    )

    if word == "of":
        value = 0.13
    elif word in TIME_UNITS and number_nearby:
        value = 0.30
    elif word in MEASURE_UNITS and number_nearby:
        value = 0.25
    else:
        value = 0.0

    recent.append(prefix.token_strings[-1])
    return (doc, recent[-3:]), value

programs.sol:
"""Approximate a signed spacing response at opening punctuation.

Spaces directly after brackets are strongly negative, especially a separate
space token. Unspaced letters are modestly positive, strongest after the
token ' ('. Letter case and length refine that response; long fragments
with internal capitals are subdued. Escaped math brackets are weaker.
Newline-following, space-prefixed words are positive. Weaker rules cover
quotes, angle brackets, slashes, bars, and repeated spaces. Else stay quiet.
These are fitted surface rules, not a parser or a token-ID lookup.
"""
READS = ()

# Unspaced letter, space-prefixed content, and separate-space responses.
BRACKETS = {
    '(': (0.17, -3.1, -4.75),
    '[': (0.20, -2.65, -4.85),
    '{': (0.17, -1.65, -3.0),
}
WIDE_BRACKETS = {'（': '(', '【': '[', '｛': '{'}


def response(previous, token):
    end, first = previous[-1:], token[:1]
    family = WIDE_BRACKETS.get(end, end)
    spaced = first in (' ', '\t')
    if family in BRACKETS:
        letter, content, blank = BRACKETS[family]
        if previous.endswith(('\\(', '\\[')):
            if spaced:
                return -1.25 if token == ' ' else -0.8
            return 0.05
        if spaced:
            if token == ' ':
                bare = previous == end and family != '{'
                return blank + (0.35 if bare else 0.0)
            if first == '\t':
                return -2.4 if family == '{' else -3.0
            if token.isspace():
                if family == '{':
                    return -1.5
                return -3.2 if '\n' in token else -2.6
            char = token[1:2]
            if char in (')', ']', '}', ','):
                return -0.7 if family == '{' else -1.15
            if char in ('(', '['):
                return -1.3 if family == '{' else -2.25
            if char == '{':
                return -1.3
            return content - (0.45 if char in ('$', '!', '\\', "'") else 0.0)
        if first.isalpha() and first.isascii():
            if len(token) >= 4 and any(c.isupper() for c in token[1:]):
                return 0.0
            if previous == ' (':
                if first.isupper() and len(token) == 1:
                    return 0.6
                if first.isupper() and len(token) >= 4:
                    return 0.25
                return 0.42
            if first.isupper() and len(token) >= 4:
                return 0.0
            return 0.25 if previous == ' [' else letter
        if first.isdigit():
            return 0.12 if family == '(' else 0.07
        if first and not first.isspace():
            return -0.4 if family == '[' else -0.15
    if previous.endswith('\n') and first == ' ' and not token.isspace():
        return 0.64 if token[1:2].isalpha() else 0.36
    if end in ('<', '«', '⟨') and spaced:
        return -0.9 if token == ' ' else -0.6
    opening_quote = previous in (' "', " '", ' `')
    quote_after_bracket = previous.startswith('(') and end in ('"', "'")
    if (opening_quote or quote_after_bracket) and spaced:
        return -1.5 if token == ' ' else -0.65
    if previous in ('/', ' /'):
        if spaced:
            return -0.5 if previous == '/' else -0.2
        if first.isalpha():
            return 0.07 if previous == '/' else -0.14
    if end == '|' and spaced:
        return -0.35 if token == ' ' else -0.12
    if token == ' ' and previous in (' ', '\xa0'):
        return -0.23 if previous == ' ' else -1.1
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(response(previous, token))

programs.luna:
"""Notice a literal space after an opening delimiter.

The predictor is zero almost everywhere. It gives a negative response when a
token begins with a space after ``(``, ``[``, ``{``, or ``<``; the response is
stronger after parentheses and square brackets. It uses stronger values for
``Figure`` after a spaced parenthesis, ``type``/``value``/``description`` after
an opening brace, and ``fprintf`` near C allocation-error cues. This is a
formatting cue, not a general parser for math or source code.
"""

READS = ()

OBJECT_FIELDS = {"type", "value", "description"}
OPENING_GAP = {"(": -1.5, "[": -1.0, "{": -0.3, "<": -0.3}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().strip(".,:;{}()[]\"'")
    value = 0.0
    opener = previous.rstrip()[-1:] if previous.rstrip() else ""

    if token.startswith(" ") and opener in OPENING_GAP:
        value = OPENING_GAP[opener]
        if opener == "(" and word == "Figure":
            value = -3.4
        elif opener == "{" and word in OBJECT_FIELDS:
            value = -0.5
        elif opener == "{" and word == "fprintf" and any(
            cue in previous for cue in ("malloc", "sizeof", "stderr")
        ):
            value = -2.3

    recent = (previous + token)[-160:]
    return (doc, recent), float(value)

programs.sol:
"""A sparse lexical approximation of a becoming / state-description signal.

Forms of 'become' are strongest; other state verbs and 'as'/'into' are
weaker. Short phrases distinguish role-marking 'serve as' from 'such as',
and ability/future 'can be' from necessity/possibility 'must/may be'.
A second, negative lexical sense is sliding and lubrication. These rules
use two preceding tokens, reset at document boundaries, and are not a parser.
"""
READS = ()

# Inflected verbs of entering or continuing a state.
STATE_VERBS = {
    'become': 5.4, 'became': 4.6, 'becomes': 4.3, 'becoming': 5.1,
    'remain': 1.35, 'remains': 1.35, 'remained': 1.35, 'remaining': 0.6,
    'being': 1.35, 'been': 0.4,
    'get': 0.65, 'gets': 0.8, 'got': 0.8, 'gotten': 0.8, 'getting': 1.0,
    'stay': 0.8, 'stays': 0.8, 'stayed': 0.8, 'staying': 0.8,
    'grow': 0.7, 'grows': 0.7, 'grew': 0.7, 'grown': 0.4, 'growing': 0.4,
}
SLIDING = {
    'slide': -0.9, 'slides': -1.0, 'slid': -1.25, 'sliding': -2.05,
    'slippery': -1.5, '滑': -4.7, '下滑': -2.7,
    '润滑': -2.2, '潤滑': -2.2, '滚': -1.0, '滾': -1.6,
}
OBJECTS = {'it', 'them', 'him', 'her', 'me', 'us', 'you'}
MAKE = {'make', 'makes', 'made', 'making'}
TURN = {'turn', 'turns', 'turned', 'turning'}


def response(token, previous, before):
    word = token.strip().lower()
    prev = previous.strip().lower()
    prior = before.strip().lower()
    capital = token.strip() != word
    spaced = token[:1].isspace()

    if word == 'as':
        if capital:
            return 0.4 if token.strip().isupper() else 0.5
        if not spaced:
            return 0.17 if previous[-1:].isalpha() else 0.55
        if prev in {'such', 'same', 'long', 'much'}:
            return 0.0
        if prev in {'well', 'far'}:
            return -0.2
        if prev in {'soon', 'early', 'good', 'simple', 'high', 'low'}:
            return 0.15
        if prev in {'serve', 'serves', 'served', 'serving'}:
            return 2.25
        if prev in {'act', 'acts', 'acted', 'acting', 'regarded', 'recognized'}:
            return 1.55
        if prev == 'used':
            return 1.65
        if prev in {'known', 'defined'}:
            return 0.53
        if prev in OBJECTS or prev.endswith(('self', 'selves')):
            return 1.2
        return 0.85
    if word == 'be':
        if capital or not spaced:
            return 0.18
        if prev in {'to', 'can', 'cannot', 'will', "'ll", '’ll'}:
            return 1.4 if prev == 'to' and prior == 'out' else 0.68
        if prev in {'may', 'might', 'should'}:
            return 0.05
        if prev in {'must', 'need'}:
            return -0.1
        return 0.4
    if word == 'into':
        if capital:
            return 0.45
        if prev in TURN or prev in OBJECTS and prior in TURN:
            return 2.1
        return 0.88 if spaced else 0.55
    if word == 'being' and prev == 'up':
        return 2.6
    if word == 'been' and prev in {'had', 'having'}:
        return 0.63
    if word == 'get':
        if capital:
            return 0.35
        if not spaced or prev in {'=', '{', '>', 'int', 'function', 'def'}:
            return 0.15
    if word in STATE_VERBS:
        value = STATE_VERBS[word]
        return value * 0.7 if capital and word.startswith(('bec', 'remain')) else value
    if word in OBJECTS and prev in MAKE:
        if word in {'it', 'them'}:
            return 0.95 if prev == 'making' else 0.78
        return 0.3
    if word.endswith(('self', 'selves')):
        return 0.65 if word in {'himself', 'themselves'} else 0.4
    # A small multilingual counterpart to becoming, being, and 'as'.
    if word in {'成为', '成為', '成为了'}:
        return 2.1
    if word in {'变', '變', '变为', '变成', '变成了'}:
        return 1.35
    if word in {'变得', '變得'}:
        return 1.8
    if word == '被':
        return 0.95
    if word in {'als', 'como', 'werden'}:
        return 0.7 if spaced or not previous[-1:].isalpha() else 0.1
    if word == 'menjadi':
        return 1.9
    if word.startswith('lubric'):
        return -1.5
    return SLIDING.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    token = prefix.token_strings[-1]
    return (doc, token, previous), response(token, previous, before)

programs.haiku:
"""layers.0.mlp.down_proj:1992 - a "becoming / taking on a role" detector.

The component fires on the word that introduces a new state or role for a subject:
  - the become family ("become", "became", "becomes", "becoming"): strongest, about 5;
  - linking verbs of staying or getting: "remain", "stay", "grow", "get" ("you will get
    tired"), about 0.6-0.8, and "being" about 1.4;
  - "as" introducing a role: "served as", "act as", "regarded as" about 1.3; other "as"
    about 0.7; "as" in "such as", "as well as", "as far as" is about 0
    (not a role);
  - "be" and "been" after "to", "will", "can", "has": about 0.5; "be" after a modal of
    necessity or possibility ("must be", "may be") about 0;
  - "into" (as in "turned into", "plug into"): about 0.8.
Every other token predicts 0. The values are the mean activation of each group on
training text, so the program is a lookup from words (and one word of left context)
to those means. It needs only the current token and the one before it.
"""
READS = ()

BECOME = {"become", "becomes", "became", "becoming"}
GET = {"get", "gets", "got", "getting"}
STAY = {"remain", "remains", "remained", "stay", "stays", "stayed", "staying",
        "grow", "grows", "grew", "growing", "gain", "gained"}
ROLE_VERBS = {"serve", "serves", "served", "serving", "act", "acts", "acted", "acting",
              "used", "treated", "identified", "known", "defined", "regarded"}
NOT_ROLE = {"such", "well", "far", "long", "same", "so", "soon", "early", "much"}
NO_BE = {"must", "may", "might", "should", "could"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in BECOME:
        return None, 4.9
    if word in STAY:
        return None, 0.8
    if word in GET:
        return None, 0.6
    if word == "being":
        return None, 1.4
    if word == "as":
        if prev in NOT_ROLE:
            return None, 0.0
        if prev in ROLE_VERBS:
            return None, 1.3
        return None, 0.7
    if word == "be":
        return None, 0.05 if prev in NO_BE else 0.55
    if word == "been":
        return None, 0.4
    if word == "into":
        return None, 0.8
    return None, 0.0

programs.sol:
"""Approximate lexical detector for 'drop' and drop-like action words.

The drop/crop/prop spelling family is central, especially 'drop' and 'rop'.
Selected short physical-action verbs get smaller, shared family values;
regular inflections and a few fragments are recognized without parsing senses.
The CJK expressions and Cyrillic 'op'-like chunks extend those lexical cues.
An immediately following 'of' inherits 35% of the preceding token's response,
within the same document. Unrecognized tokens get zero: this deliberately
omits the component's many weaker background responses.
"""
READS = ()

# Approximate sizes for recognizable word families, not arbitrary token IDs.
FAMILIES = (
    (-1.5, 'stop strip'),
    (-1.3, 'split skip jump collapse'),
    (-1.8, 'hop'),
    (-1.1, 'break clip pop wrap snap flip chop'),
    (-0.75, 'step trip slip fall leap'),
    (-0.5, 'throw track rip grip whip bump'),
    (-0.4, 'trim dip'),
    (-1.5, 'dropdown dropout backdrop'),
)
ROOTS = {w: v for v, words in FAMILIES for w in words.split()}
ROOTS.update(drop=-5.7, crop=-3.0, prop=-1.2, trop=-1.2)


def response(token):
    text = token.strip().lstrip('._-(\"\'')
    word = text.lower()
    if word in {'rop', 'rops', 'ropped', 'dro'}:
        return {'rop': -2.8, 'rops': -2.5, 'ropped': -4.1, 'dro': -1.2}[word]
    if word in {'broke', 'broken', 'fallen', 'fell', 'thrown', 'unwrap'}:
        return -0.7
    if word in {'pped', 'opped', 'ipped', 'pping'}:
        return -0.9
    if word in {'ipping', 'opping', 'apping', 'apped', 'ops'}:
        return -0.4
    if word == 'оп':
        return -0.2 if token[:1].isspace() else -0.55
    if word in {'поп', 'кап', 'доп'}:
        return -0.8
    root = word
    for ending in ('ing', 'ed', 's'):
        if word.endswith(ending) and word not in ROOTS:
            root = word[:-len(ending)]
            if root.endswith(('pp', 'tt')):
                root = root[:-1]
            if root + 'e' in ROOTS:
                root += 'e'
            break
    if root in ROOTS:
        value = ROOTS[root]
        if root == 'drop':
            value = -5.3 if word != root else -5.7
            if text.isupper() or token.startswith(('_', '.')):
                value = -5.0
        elif root == 'crop' and word != root:
            value = -2.0
        elif word == 'stepping':
            value = -1.2
        elif word == 'chopped':
            value = -1.7
        elif word == 'props':
            value = -1.7
        elif word in {'wrapped', 'wrapping', 'hopping'}:
            value = -0.85
        elif root in {'split', 'strip'} and not token[:1].isspace():
            value -= 0.5
        elif root in {'skip', 'trim'} and token.startswith('.'):
            value -= 0.5
        elif root == 'snap' and text[:1].isupper():
            value = -0.8
        return value
    # Jump; dropping/stopping/bursting; breaking/removal; steps and props.
    if text == '跳':
        return -3.3
    if text in set('掉停爆滴丢弹彈跌'):
        return -1.5
    if text in set('降破拆翻扔'):
        return -1.1
    if text in {'停止', '断', '落', '啪', '步', '歩', '止め', '摔', '脱', '漏', '道具'}:
        return -0.75
    # Abandon; descent/steps/splitting; jumping.
    if text == '抛弃':
        return -2.3
    if text in {'下降', '步骤', '一步', '分裂', '分割', '降低', '落地'}:
        return -0.6
    if text == '跳跃':
        return -1.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = response(token)
    if (token.strip().lower() == 'of' and prefix.position > 0
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        value = 0.35 * response(prefix.token_strings[-2])
    return None, float(value)

programs.haiku:
"""Sudden stop / break / fall verbs (English and Chinese). The component is negative on the
verb token itself, most strongly on "drop" (and its fragment "rop" of drop/crop), and weaker
on stop, split, strip, jump, skip, pop, break, wrap, snap, step, trip, slip, fall.
Chinese verbs of stopping, dropping, breaking, jumping and falling (停 掉 爆 跳 拆 破 落 降 跌 摔)
also drive it negative. Everything else is near zero."""
import re
READS = ()
STEMS = {
    "drop": -5.5, "rop": -3.0, "crop": -2.0, "strip": -2.0, "split": -1.5, "stop": -1.5,
    "jump": -1.3, "skip": -1.2, "chop": -1.2, "pop": -1.1, "break": -1.1, "clip": -1.0,
    "wrap": -1.0, "snap": -1.0, "flip": -1.0, "step": -0.8, "trip": -0.7, "slip": -0.7,
    "fall": -0.6,
}
SUFFIX = r"(s|es|ed|ing|ped|ping|ting|ning|ding|ged|ging|ming|ned|ded|en|ten)?"
PATTERNS = [(re.compile("(un)?" + stem + SUFFIX), value) for stem, value in STEMS.items()]
CHARS = {"停": -1.8, "掉": -1.8, "爆": -1.4, "跳": -3.4, "拆": -1.1, "破": -1.0, "落": -0.9,
         "降": -1.0, "跌": -1.3, "摔": -0.9}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    for ch, value in CHARS.items():
        if ch in s:
            return None, value
    w = "".join(c for c in s.lower() if c.isalpha())
    if w == "broken" or w == "broke":
        return None, -0.8
    for pattern, value in PATTERNS:
        if pattern.fullmatch(w):
            return None, value
    return None, 0.0

programs.luna:
"""Approximate a sparse negative signal on drop and other action words.

Drop forms get the largest prediction; a short English verb list and selected
Chinese/Japanese movement words get a smaller one. Other tokens get zero.
"""

READS = ()

DROP_WORDS = {"drop", "drops", "dropped", "dropping"}
ACTION_STEMS = {
    "break", "swap", "propel", "track", "stitch", "kidnap", "fall",
    "throw", "step", "trip", "stop", "jump", "slip", "split", "chop",
    "trim", "stumble", "bump", "wrap", "snap", "toss", "push", "pull",
    "kick", "hit",
}
IRREGULAR_ACTIONS = {"broke", "broken", "fell", "fallen", "threw", "thrown"}
CJK_ACTIONS = {
    "降", "下降", "掉", "扔", "停止", "止め",
    "脱", "落", "跌", "摔", "破", "跳",
}


def is_action(word):
    if word in ACTION_STEMS or word in IRREGULAR_ACTIONS:
        return True
    for ending in ("ing", "ed", "es", "s"):
        if not word.endswith(ending):
            continue
        root = word[:-len(ending)]
        doubled = root[:-1] in ACTION_STEMS
        restored_e = root + "e" in ACTION_STEMS
        if root in ACTION_STEMS or doubled or restored_e:
            return True
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous_doc, partial = carry if carry is not None else (doc, "")
    if doc != previous_doc:
        partial = ""

    token = prefix.token_strings[-1]
    fresh = any(ch.isalpha() for ch in token)
    if any(ch.isspace() for ch in token):
        pieces = token.split()
        partial = pieces[-1] if pieces else ""
    else:
        partial = (partial + token)[-24:]

    word = "".join(ch for ch in partial.lower() if ch.isascii() and ch.isalpha())
    value = 0.0
    if fresh:
        if word in DROP_WORDS:
            value = -5.2
        elif is_action(word):
            value = -0.9
        elif any(term in token or partial.endswith(term) for term in CJK_ACTIONS):
            value = -0.9
    return (doc, partial), value

"""Respond to explicit measuring, testing, and evaluation language.

The strongest cues are measurement words and the phrase "measurement of";
other checking and quantity terms receive smaller positive guesses.
"""

READS = ()

STRONG_MEASURE = ("measure", "measurement", "measuring")
OTHER_MEASURE = (
    "metric", "gauge", "degree", "scale", "quantity", "unit",
    "estimate", "calculate", "compute", "determine", "definition",
    "scaling",
)
CHECKING = (
    "test", "verify", "assert", "evaluation", "evaluate", "judge",
    "criteria", "monitor", "probe", "label", "standard",
)


def step(carry, prefix, upstream):
    """Use the current word and its immediate predecessor as simple cues."""
    token = prefix.token_strings[-1].strip().lower()
    document = prefix.document_ids[-1]
    previous_doc, previous = carry if carry is not None else (None, "")
    if document != previous_doc:
        previous = ""

    if token in ("of", "the") and previous in (
        "measurement", "measure", "evaluation", "estimate"
    ):
        value = 2.3
    elif any(word in token for word in STRONG_MEASURE):
        value = 2.3
    elif any(word in token for word in OTHER_MEASURE):
        value = 0.55
    elif any(word in token for word in CHECKING):
        value = 0.9
    elif token in ("标准", "表", "ランキング", "суд"):
        value = 0.65
    else:
        value = 0.0

    return (document, token), value

programs.sol:
"""Negative responses to unchanged-spelling verbs and directional words.

The main lexicon is English verbs such as cut, set, put, let, read and run,
whose base and past/participle forms share a spelling. Inflections respond
more weakly. Related particles, compounds and Chinese/Japanese spellings
are included. The preceding token supplies simple grammatical clues:
"to" and modals weaken the response; forms of "be" strengthen it, and
"set up" is especially strong. Case and identifier separators adjust the
magnitude. These are token-spelling rules, not a full-word or tense parser;
unlisted spellings predict zero. State resets at document boundaries.
"""
READS = ()

# Verbs with unchanged past or participle spelling; magnitudes differ by word.
VERBS = {
    'cut': 2.1, 'cast': 2.0, 'run': 1.85, 'split': 1.7,
    'read': 1.4, 'put': 1.35, 'set': 1.3, 'hit': 1.3,
    'let': 1.1, 'spread': 1.15, 'hurt': 1.25, 'shut': 1.1,
    'burst': 1.05, 'beat': 1.1, 'knit': 0.95, 'bet': 0.9,
    'slit': 0.85, 'bid': 0.7, 'wet': 0.55, 'shed': 0.6,
    'quit': 0.55, 'spit': 0.5, 'cost': 0.35, 'fit': 0.75,
}
# Related short past forms, directional particles, and compounds.
PARTICLES = frozenset(('up', 'out', 'down', 'off', 'forth'))
PAST_FORMS = frozenset(('won', 'ran', 'sent', 'slid', 'bent'))
RELATED = {
    'won': 1.45, 'shot': 1.4, 'ran': 1.0, 'sent': 0.6,
    'slid': 0.75, 'bent': 0.55,
    'out': 0.85, 'up': 0.6, 'down': 0.6, 'off': 0.22,
    'forth': 0.45,
    'input': 1.0, 'output': 1.5, 'offset': 1.25,
    'upset': 1.9, 'reset': 0.85, 'onset': 0.5, 'setup': 0.55,
    'broadcast': 1.1, 'forecast': 1.0, 'undercut': 1.7,
    'overcome': 0.5, 'sunset': 0.9,
}
INFINITIVE = frozenset('to can could will would shall should may might must'.split())
PARTICIPLE = frozenset('be been being is are was were am'.split())
# Translations of running, setting, input/output, reading and losing.
TRANSLATIONS = {
    '运行': 1.05, '運行': 1.05, '跑': 1.0, 'セット': 0.85,
    '输入': 0.85, '輸入': 0.85, '输出': 1.0, '輸出': 1.0,
    '出': 0.6, '出来': 0.5, '出來': 0.5, '出了': 0.5,
    '阅读': 0.5, '閱讀': 0.5, '读': 0.5, '讀': 0.5,
    '输了': 0.95, '輸了': 0.95,
}


def lexical_form(token):
    """Strip identifier separators; recognize a few ordinary inflections."""
    word = token.strip().strip('.,:_-/()[]{}!;\\\'"`').lower()
    if word in VERBS or word in RELATED:
        return word, 1.0
    if word in ('runner', 'runners'):
        return 'run', 0.36
    if word == 'running':
        return 'run', 0.55
    if word in ('setter', 'setters'):
        return 'set', 0.25
    if word == 'ready':
        return 'read', 0.25
    if word == 'runtime':
        return 'run', 0.2
    for ending, scale in (('s', 0.35), ('ing', 0.1)):
        if word.endswith(ending):
            root = word[:-len(ending)]
            if root not in VERBS and len(root) > 2 and root[-1:] == root[-2:-1]:
                root = root[:-1]
            if root in VERBS or root in RELATED:
                if ending == 's':
                    if root == 'run':
                        scale = 0.7
                    elif root == 'input':
                        scale = 1.0
                    elif root in ('set', 'put', 'read', 'bet', 'output'):
                        scale = 0.55
                elif root in ('put', 'read', 'cut'):
                    scale = {'put': 0.3, 'read': 0.35, 'cut': 0.2}[root]
                return root, scale
    return '', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word, scale = lexical_form(token)
    magnitude = VERBS.get(word, RELATED.get(word, 0.0)) * scale
    if magnitude:
        raw = token.strip().strip('.,:_-/()[]{}!;\\\'"`')
        if token.startswith('.'):
            factor = 0.2 if word in PARTICLES else 1.1
            magnitude *= 0.75 if word in VERBS else factor
        elif token.startswith('/'):
            magnitude *= 1.25
        elif token.startswith('-'):
            magnitude *= 1.1
        elif token.startswith('_') or token.startswith('\t'):
            magnitude *= 0.85
        elif not token.startswith(' ') and raw.islower():
            if word in PAST_FORMS:
                magnitude = 0.0
            else:
                magnitude *= 0.55 if word in PARTICLES else 0.75
        if raw.isupper():
            magnitude *= 0.85
        if word in VERBS and scale == 1.0:
            if previous == 'to':
                magnitude *= 0.55
            elif previous in INFINITIVE:
                magnitude *= 0.65
            elif previous in PARTICIPLE:
                magnitude *= 1.25
            elif previous.isspace():
                magnitude *= 0.75
        if word == 'up':
            if previous in ('set', 'sets', 'setting'):
                magnitude += 1.1
            elif (previous in ('made', 'came', 'grew', 'took', 'woke')
                  or previous.endswith('ed')):
                magnitude += 0.15
    if not word:
        magnitude = TRANSLATIONS.get(token.strip(), 0.0)
    newest = token.strip().lower()
    if token.isspace():
        newest = token
    return (doc, newest), float(-magnitude)

programs.haiku:
"""LaTeX command names: the letters that follow a backslash, e.g. 'frac' in \\frac.
Math operators and symbols strong; Greek letters weaker; font/layout commands near zero;
code escapes (\\n, \\t, \\x in program strings) near zero. Plain 'sqrt' / '√' also fire."""

READS = ()

GREEK = frozenset(
    "alpha beta gamma delta epsilon varepsilon zeta eta theta vartheta iota kappa lambda mu nu xi "
    "pi varpi rho varrho sigma varsigma tau upsilon phi varphi chi psi omega".split()
)
MATH = frozenset(
    "frac sqrt rightarrow leftarrow to ge le geq leq left right times cdot infty in text "
    "mathrm Large large boxed over sim cong eq ast prime dfrac".split()
)
FONT = frozenset("mathbf mathcal bold boldsymbol hspace hfill".split())


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    inside, word = carry if carry is not None else (False, "")
    letters = tok.isascii() and tok.isalpha()
    if letters and same_doc and prev.endswith("\\"):
        inside, word = True, tok
    elif letters and inside:
        word = word + tok
    else:
        inside, word = False, ""
    carry = (inside, word)
    if tok.strip() in ("sqrt", "√"):
        return carry, 0.9
    if not inside or len(word) < 2:
        return carry, 0.0
    if word in MATH:
        return carry, 1.5
    if word in GREEK:
        return carry, 0.4
    if word in FONT:
        return carry, 0.1
    if word[0] in "ntx":
        return carry, 0.0
    return carry, 1.0

programs.luna:
"""Predict pulses on structural and formatting commands in TeX math.

The examples show strong responses to fractions, delimiters, arrows,
references, and text/font markup. This predicts larger pulses on a selected
set of those TeX commands, smaller ones on Greek-letter commands, and a
modest pulse on the square-root sign. A few split command names are handled.
