def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    previous = prefix.token_strings[-2].rstrip() if len(prefix) > 1 else ""
    before_previous = prefix.token_strings[-3].rstrip() if len(prefix) > 2 else ""
    if prefix.position and prefix.document_ids[-1] != prefix.document_ids[-2]:
        previous = before_previous = ""

    if previous.endswith("\\"):
