            value = -4.2
        elif spelling in {'恢复', '恢復', '回復'}:
            value = -3.1
        elif spelling in {'复合', '复制', '复活', '复兴', '复习', '复试'}:
            value = -2.1
        else:
            value = -1.4
    elif word in {'reply', 'replies', 'replied', 'plies'}:
        if word == 'reply':
            value = -3.4 if spelling[:1].isupper() else -1.9
        else:
            value = -2.4 if spelling == 'Replies' else -1.45
    elif word.startswith('recover') or word == 'covery':
        value = -2.25 if word == 'recovery' else -1.65
    elif word in {'complex', 'complexes', 'plex'}:
        value = -1.1
    elif word.startswith('complex') or word == 'complicated':
        value = -0.3
    elif word in {'replica', 'replicas'}:
        value = -1.4
    elif word in {'repeating', 'peating', 'peated'}:
        value = -1.05
