            (('restor',), -1.0),
            (('repeat', 'repet', 'replic', 'reprodu'), -0.65),
            (('composite', 'compound', 'posite', 'posites'), -0.6),
            (('duplic', 'uplic', 'copy', 'copied', 'copies'), -0.45),
            (('reviv', 'rehab', 'recuper', 'reopen'), -0.7),
            (('rebuild', 'renew', 'resume', 'retriev'), -0.45),
            (('повтор', 'комплекс', 'récup'), -0.75),
