programs.luna:
"""Approximate sparse responses to words for repeating, recovery, and composites.

Several harvested responses landed on later pieces of a split English word, so
the program carries just the current word fragment and resets it at word breaks.
It gives negative values only to this spelling family.
"""

READS = ()


def response(word):
    if word.startswith(("reply", "replica", "repeat", "repro", "recover")):
        return -0.8
    if word.startswith(("complex", "composit", "duplicat")):
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc:
        previous = carry[1]

    piece = prefix.token_strings[-1].lower()
    if piece[:1].isspace():
        previous = ""
    joined = previous + piece
    end = len(joined)
    while end and joined[end - 1].isalnum():
        end -= 1
    word = joined[end:]
    next_carry = (doc, word if word.isalpha() else "")
    return next_carry, response(word)

programs.sol:
"""A spacing/formatting detector, rather than a word-meaning detector.

It responds to wide blank tokens and to spaces after separately tokenized
operators or punctuation. Words weaken the boundary signal; quotes weaken
it especially strongly. An operator already containing a space is weaker.
Initial Markdown hashes, diff hunk headers, and thinking tags are
explicit special cases. Unspaced digits after strong operators are negative.
It does not reproduce arbitrary word-specific fluctuations.
"""
import math

READS: tuple[str, ...] = ()
CONJUNCTIONS = {'and', 'or', 'but', 'und', 'et', 'oder'}


def boundary(s):
    """Blank response and the fraction retained when the space has a word."""
    p = s.strip()
    if not p or '\n' in s or '\r' in s or any(c.isalnum() for c in p):
        return 0.0, 0.0
    if p[-1] in '=+^−≥≤×&→÷':
