    if word == '演':
        return 4.5
    if word == '演练':
        return 2.8
    if word in DEMONSTRATIONS:
        return 2.0
    if word in PERFORMERS:
        return 1.0
    if '演' in word:
        return 0.4 if any(c in word for c in '唱奏饰') else 1.4
    if word == '연':  # Korean syllable used in performance-related compounds.
        return 1.5 if s.startswith(' ') else 1.8
    if word == 'diễn':  # Vietnamese: perform, unfold, explain.
        return 2.25
    if word in {'練', '练'}:
        return 0.9
    if word in {'幻', '漫'}:
        return 0.75
    if word in {'舞台', '模特', '剧情', '直播', '主播'}:
        return 0.33

