            return 2.17
        if previous_id == 6567:  # space + E6
            return 4.1
        if previous_id == 8620:  # space + EA
            return 1.5
        return 0.4
    if completed == '演':
        return 5.5
    if completed == 'ἔ':
        return 1.9
    if completed in {'ἀ', 'ἐ', 'ἑ'}:
        return 0.66
    if completed and '\u1f00' <= completed <= '\u1f3f':
        return 0.3
