    if low in {'simulation', 'simulations', 'illusion', 'illusions', 'elaborate'}:
        return 0.43
    if low.startswith('animation'):
        if s.startswith('.'):
            return 1.0
        return 0.6 if w.startswith('A') else 0.39
    if low == 'dramatic':
        return 0.56
    if low == 'replay':
        return 0.48
    if word == 'derive':
        return 0.1 if s.startswith(' ') else 0.49
    if low.startswith('demonstrat'):
        return 0.4 if low in {'demonstration', 'demonstrations'} else 0.24
    if low in {'simplify', 'simplified', 'animated', 'theatrical',
               'exercise', 'exercises'}:
