"""Detect openings of parentheticals and written references.

The strongest rules mark LaTeX cross-references, citations and labels,
Markdown link destinations, and markup IDs/URLs. Smaller rules mark ordinary
opening parentheses and relative paths. The preceding token separates prose
asides from arithmetic and control-flow parentheses. All other tokens receive
a near-zero baseline; document boundaries reset the short text history.
"""
import re

READS = ()
LATEX_COMMAND = re.compile(r'\\([A-Za-z]+)$')
REFERENCE_COMMANDS = {'ref', 'eqref', 'autoref', 'pageref', 'cref', 'Cref'}
FUNCTION_WORDS = set('a an the of in on to at from and or with by as that'.split())


def response(token, previous, tail):
    s, p = token.strip(), previous.strip()
    # Link destinations and explicit reference markers.
    if token.endswith(']('):
        if '![' in tail.rsplit('\n', 1)[-1]:
            return 5.8
        return 4.3 if '[](' in token else 3.26
    if s == '[@':
        return 3.10
    if s in {'link', 'linkplain'} and tail.endswith('@'):
        return 6.1 if tail.endswith("'{@") else 3.9
    if token == '-type' and p == 'ref':
        return 2.84
    if token == '（':
        return 0.56
    if re.search(r'(?:\.\./|\./)+$', token):
        if any(c in token for c in "\"'"):
            return 2.3
        if token.count('../') > 1:
            return 1.7
        return 0.9 if '../' in token else 0.33

    # LaTeX commands and the opening delimiter of their argument.
    if token in REFERENCE_COMMANDS and re.search(r'\\(?:eq|auto|page|c)?$', tail):
        return 7.0 if tail.endswith(' (\\') else 5.65
    if token in {'label', 'cite'} and tail.endswith('\\'):
        return 4.27 if token == 'label' else 2.94
    if token in {'{', ']{', ' {'}:
        command = LATEX_COMMAND.search(tail)
        name = command[1] if command else ''
        if name in REFERENCE_COMMANDS:
            return 7.15
        if name.startswith('cite'):
            return 5.77
        if name == 'label':
            return 6.01
        if name in {'begin', 'end'}:
            return 1.39
        if 'includegraphics' in tail.rsplit('}', 1)[-1]:
            return 8.70
        if name in {'frac', 'dfrac', 'tfrac', 'text', 'mathrm'}:
            return -0.17
        if name:
            return 0.51
        return 0.27 if token == ' {' else 0.61
    if token == '\\[' or (token == '[' and tail.endswith('\\')):
        if previous == '\u00a0':
            return 4.67
        if previous.endswith('(\\'):
            return 4.8
        return 1.3 if '"' in previous else 2.6

    # Quoted attribute values and URL fragments.
    if token.startswith('="#'):
        return 4.2 if p.lower() in {'href', 'id', 'xlink:href'} else 2.2
    if token in {'="', "='", '=\\"'}:
        if p.lower() in {'id', 'href', 'cref', 'ref'}:
            return 3.55
        if p.lower() == 'src':
            return 2.45
        if p in {'class', 'className'}:
            return 1.56
        if p in {'name', 'style', '-type', '-label', 'for'}:
            return 1.35
        return 0.4
    url_fragment = '](' in tail[-12:] or re.search(r'\.(html|md|xhtml)$', tail)
    if token.startswith('#') and url_fragment:
        return 4.48
    if s in {'#', '##', '###', '####'}:
        return -0.045 if len(s) > 1 else 0.24

    # Prose asides are stronger than arithmetic/control-flow parentheses.
    if token == ' (':
        if p == '=':
            return -0.18
        if p in {'+', '-', '(', '[', ':', '=>'}:
            return -0.01
        if p in {',', '.', ';', '?', '*', '/'}:
            return 0.19
        if p.isnumeric():
            return 0.423
        if not p:
            return 0.18
        if p in {'if', 'for', 'while', 'switch', 'is', 'are', 'be', 'as'}:
            return 0.035
        if previous[:1].isspace() and p.lower() in FUNCTION_WORDS:
            return 0.19
        if p in {'subsection', 'subparagraph', 'clause'}:
            return 1.0
        if p.isalpha():
            return 0.66 if previous[:1].isspace() and len(p) > 3 else 0.56
        return 0.45
    if token in {' (-', ' (!'}:
        return -0.22
    if '(' in token and any(c in token for c in "\"'"):
        if re.search(r'(ById|TestId)$', p):
            return 4.0
        if re.search(r'(print|printf|Printf|println|replace|split|join|append)$', p):
            return 0.02
        return 0.185
    if token.endswith('('):
        if '\\' in token:
            return 0.23
        return 0.41 if s == '(' or token[0] in ')}' else 0.55
    return 0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (document, token, (tail + token)[-200:]), value

