EXCEPTION = re.compile(r"[ .]?[A-Z][A-Za-z]+(Error|Exception)")


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if word in LOGO:
        value = -1.2
    elif word in DESIGN:
        value = -0.2
    elif EXCEPTION.fullmatch(text):
        value = -0.25
    elif any(p in text for p in POLITICS):
