programs.sol:
"""Approximate vowel joins between adjacent tokens.

Repeated vowels give a positive signal (o-o is strongest); o followed by a,
e or i is usually negative, while o-u is positive. Short fragments have
stronger joins than word-sized tokens. Spaces, mixed-case starts and vowel runs modify the signal. A lone vowel
at a row or document start has its own positive response. Greek and Cyrillic vowels are included.
"""
import unicodedata

READS = ()
VOWELS = {'а': 'a', 'α': 'a', 'е': 'e', 'э': 'e', 'ε': 'e',
          'и': 'i', 'ι': 'i', 'о': 'o', 'ο': 'o', 'у': 'u',
          'υ': 'u', 'я': 'ya', 'ю': 'yu'}
JOIN = {'aa': 0.66, 'ee': 0.85, 'ii': 0.19, 'oo': 3.12, 'uu': 0.26,
        'oa': -0.94, 'oe': -0.40, 'oi': -0.48, 'ou': 0.74,
        'oya': -1.27, 'oyu': -0.87}
INITIAL = {'a': 0.35, 'e': 0.53, 'i': 0.10, 'o': 2.0, 'u': 0.23}
LENGTH_SCALE = (0.0, 0.8, 1.0, 0.88, 0.73, 0.47, 0.25)


def vowel(c):
    decomposed = unicodedata.normalize('NFD', c.lower())
    if decomposed.startswith('υ') and '\u0308' in decomposed:
        return 'i'  # Greek upsilon with diaeresis is not the ou digraph.
    c = decomposed[:1]
    return VOWELS.get(c, c)


def join(previous, text):
    clean = text.lstrip()
    if not clean:
        return 0.0
    spaced = text[0].isspace()
    if not previous:
        return (INITIAL.get(vowel(clean), 0.0) * (0.5 if spaced else 1.0)
                if len(clean) == 1 else 0.0)
    hyphenated = clean.startswith('-')
    if hyphenated:
        clean = clean[1:]
    if not clean:
        return 0.0
    pair = vowel(previous[-1]) + vowel(clean[0])
    if pair not in JOIN:
        return 0.0
    q = LENGTH_SCALE[len(clean)] if len(clean) < 7 else 0.15
    if spaced:
        if pair == 'oo' and not clean.lower().startswith('ou'):
            strong = previous.strip().lower() in {'no', 'so', 'do', 'go'}
            return q * (0.86 if strong else 0.16)
        return 0.025 if pair in {'aa', 'ee', 'ii', 'uu'} else 0.0
    if len(clean) == 1 and pair in {'oa', 'oe', 'oi'} and clean.isascii():
        q = {'oa': 0.4, 'oe': -0.2, 'oi': 0.25}[pair]
    if clean[0].isupper() and not clean.isupper():
        q *= 0.6 if pair == 'oo' and len(clean) <= 2 else 0.1
    if len(previous.strip()) > 4 and pair != 'oo':
        q *= 0.35
    if len(clean) > 1 and vowel(clean[0]) == vowel(clean[1]):
        q *= 0.6 if pair[0] == pair[1] else 1.8
    if hyphenated:
        q *= 0.7
    if pair == 'oo' and previous[-1].lower() in 'öő':
        q *= 0.5  # Front-rounded o differs from ordinary o.
    if previous[-1].lower() == 'о':
        cyrillic_o = {'oo': 1.87, 'oe': -0.85, 'oi': -0.90, 'ou': 0.25}
        if pair in cyrillic_o:
            return cyrillic_o[pair] * q
    return JOIN[pair] * q


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    return (doc, text), float(-0.002 + join(previous, text))

