    elif word == '_replace':
        value = 0.69
    elif word.lower() in REPLACEMENT_WORDS:
        value = 0.19
    elif word in DOM_LOOKUP:
        value = 0.65
    elif word in {'.readlines', '.readFileSync', '.cwd'}:
        value = 0.86
    elif word in {'.makedirs', '.getcwd', 'dirname'}:
        value = 0.45 if token == word else 0.10
    elif word in PRESENCE_TESTS:
        value = 0.40
    elif word in COLLECTION_LOOKUP:
        value = 0.30
    elif word == '.findById':
        value = 0.85
    elif word.startswith('.get'):
        value = 0.13
    elif word.startswith('.set') and word not in {'.settings', '.setup'}:
        value = -0.16
    elif word == '.prototype':
        value = -0.55
    elif word in {'toString', '.toString'}:
        value = -0.25
    elif word == '.Errorf':
        value = 0.48
    elif word == 'sizeof':
        value = 0.35
    elif word in {'(sizeof', '*sizeof'}:
        value = 0.54
    elif word in {'malloc', 'calloc', 'strcmp', 'strlen'}:
        value = 0.30
    elif word == '_modules':  # e.g. the dependency directory node_modules
        value = 0.21
    elif word == 'respectively':
        value = 0.21
    elif word in {'both', 'also', 'each'}:
        value = 0.05
