programs.haiku:
"""Layer-0 MLP down_proj component 2009: a copula and clause-joining detector.

What it does, in plain terms:
- It is near zero on almost every token.
- On the present-tense copula "is", "are" or "am" in an ordinary clause ("the product is",
  "they are", "it is") it is positive, about +1.
- Right after a clause-joining conjunction ("and", "but", "or") the sign flips. A following
  finite verb, modal or auxiliary ("and is", "and was", "and can", "and hasn't") is strongly
  negative, about -2. A following pronoun, preposition or comma ("and it", "and from",
  "and,") is moderately negative, about -1.2.
- A connective after "and" ("and then", "and so", "and thus", "back and forth") is positive,
  about +1.5. "and/or" is about +3.
- In existential and wh- constructions ("there was", "there's", "here's", "what's") the
  be-verb is mildly negative, about -0.8. "there is" stays at zero.
- Everything else, including "then" on its own, is zero.

The program looks only at the current token and the one before it, within the same document.
"""

READS = ()

CONJUNCTIONS = {"and", "but", "or"}
COPULA = {"is", "are", "am"}
BE_VERBS = {"was", "were", "'s", "’s"}
AUXILIARY = {
    "was", "were", "be", "can", "will", "may", "should", "must", "could", "would", "has",
    "have", "had", "does", "did", "do", "wasn", "weren", "isn", "aren", "couldn", "shouldn",
    "wouldn", "hasn", "haven", "hadn", "doesn", "didn", "don", "won", "can't", "cannot",
}
PRONOUNS_PREPOSITIONS = {
    "it", "they", "he", "she", "we", "you", "i", "to", "in", "that", "which", "if", "as",
    "when", "of", "from", "by", "at", "for", ",",
}
CONNECTIVES = {"then", "so", "thus", "hence", "therefore", "forth"}
EXISTENTIAL = {"there", "here", "what"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev_raw = prefix.token_strings[-2] if same_doc else " "
    prev = prev_raw.strip().lower()
    # A whole word starts after a space or punctuation; "am" inside "Human" does not count.
    whole = raw[:1].isspace() or not prev_raw[-1:].isalpha()
    if not whole and cur not in BE_VERBS:
        cur = ""
    if prev in CONJUNCTIONS:
        if cur in COPULA or cur in AUXILIARY:
            value = -2.0
        elif cur in CONNECTIVES:
            value = 1.5
        elif cur in PRONOUNS_PREPOSITIONS:
            value = -1.2
        elif raw == "/or":
            value = 3.0
        else:
            value = 0.0
    elif cur in COPULA:
        value = 0.0 if prev == "there" else 1.0
    elif cur in BE_VERBS and prev in EXISTENTIAL:
        value = -0.8
    else:
        value = 0.0
    return carry, float(value)

