programs.sol:
"""A lexical approximation to English object-phrase onset.

Possessives have a negative baseline. Articles, possessives and object pronouns
become more negative after common transitive verbs, especially possession and
acquisition verbs. Inflections and qualifying participles are handled roughly;
prepositions, coordination and punctuation modulate possessives. Capitalized
or unspaced possessives get a smaller constant response; unspaced 'the' gets a
small positive response. Other tokens get zero. Only the current and previous
tokens are used, with the previous token reset at document boundaries.
"""
READS = ()

# Strength classes approximate how strongly a verb introduces an object.
# The strongest classes center on acquisition, possession and physical handling;
# weaker classes include perception, transformation and description.
VERBS = [
    (4.5, 'get put'),
    (3.8, 'have make keep hold bring'),
    (3.1, 'take add need want leave obtain start carry turn pull push gain earn'),
    (2.4, '''give create build write set provide require receive share play
             move feel offer send save pay buy drive try cut hit lose'''),
    (1.9, '''use do see show read remove allow choose perform maintain run
             open follow produce help apply select watch install present call let'''),
    (1.5, '''find change reduce improve contain return reach enter join
             prevent replace adjust fix finish learn develop'''),
    (.8, '''check include calculate compute determine know consider support
            control ensure update identify measure solve verify describe'''),
]
STRENGTH = {w: s for s, words in VERBS for w in words.split()}
FORMS = {
    'have': 'has had', 'make': 'made', 'get': 'got gotten', 'keep': 'kept',
    'hold': 'held', 'take': 'took taken', 'bring': 'brought', 'give': 'gave',
    'see': 'saw seen', 'find': 'found', 'do': 'did done does', 'leave': 'left',
    'write': 'wrote written', 'send': 'sent', 'pay': 'paid', 'feel': 'felt',
    'build': 'built', 'choose': 'chose', 'run': 'ran',
}
BASE = {w: b for b, forms in FORMS.items() for w in forms.split()}


def strength(token):
    w = token.strip().lower()
    # These participles can introduce qualifications instead of verb objects.
    if w in {'given', 'following', 'including', 'provided'}:
        return .6
    if w in {'does', 'called'}:
        return .8
    # Common irregular past forms have distinct object-onset strengths.
    if w in {'had', 'made', 'took', 'held', 'kept', 'brought'}:
        return 4.
    if w in {'saw', 'found', 'felt', 'bought', 'built'}:
        return 2.8
    b = BASE.get(w, w)
    if b in STRENGTH:
        return STRENGTH[b]
    if w.endswith('ies') and w[:-3] + 'y' in STRENGTH:
        return STRENGTH[w[:-3] + 'y']
    for ending in ('ing', 'ed', 'es', 's'):
        if w.endswith(ending):
            root = w[:-len(ending)]
            for b in (root, root + 'e', root[:-1]):
                if b in STRENGTH:
                    value = STRENGTH[b]
                    return value * .9 if ending == 'ing' and value < 3. else value
    if w in {'with', 'without', 'up', 'out'}:
        return .9
    if w in {'for', 'at', 'through', 'under', 'over', 'after', 'before'}:
        return .25
    if w in {'of', 'to', 'in', 'on', 'from', 'by', 'as', 'into', 'and', 'or'}:
        return 0.
    if w.isalpha() and w.endswith(('ed', 'ing')):
        return .8
    return .12

# Possessive determiner baselines and sensitivities.
POSSESSIVES = {
    'his': (-1.14, -1.13), 'her': (-.86, -.75), 'its': (-.44, -1.16),
    'their': (-.84, -1.23), 'my': (-.86, -1.09),
    'your': (-1.17, -1.10), 'our': (-1., -1.06),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    carry = (doc, token)
    # The tokenizer's unspaced 'the' has a small positive baseline.
    if token == 'the':
        return carry, .26
    if not token.startswith(' ') or word != word.lower():
        # A token inside a larger word is not a sentence-initial possessive.
        inside_word = not token.startswith(' ') and prev and prev[-1].isalpha()
        return carry, -.6 if word.lower() in POSSESSIVES and not inside_word else 0.
    s = strength(prev)
    if word in POSSESSIVES:
        baseline, sensitivity = POSSESSIVES[word]
        value = baseline + sensitivity * s
        if prev.strip().lower() in {'of', 'and', 'or'} or not prev.strip().isalpha():
            value += .25
        return carry, value
    if word == 'the':
        return carry, .02 - s
    if word in {'a', 'an'}:
        return carry, .03 - (.29 if word == 'a' else .36) * max(0., s - .6)
    if word in {'it', 'this'}:
        return carry, .06 - (.62 if word == 'it' else .77) * s
    if word == 'that':
        return carry, .02 - .27 * max(0., s - .9)
    if word in {'some', 'all', 'any', 'each', 'these', 'those'}:
        return carry, .03 - .4 * s
    if word in {'something', 'anything', 'everything', 'nothing'}:
        return carry, -.08 - .45 * s
    if word in {'them', 'him', 'one', 'another'}:
        return carry, .03 - .28 * s
    return carry, 0.

