        return None, 0.8
    if word.startswith("command"):
        return None, 1.0
    if word.startswith("manage"):
        return None, 1.4
    if word.startswith("regulat"):
        return None, 0.6
    if word.startswith(("governance", "governing")):
        return None, 0.8
    if word.startswith(("handl", "keep", "maintain", "monitor")):
        return None, 0.8
    if word.startswith("contained"):
        return None, 0.65
    if word.startswith("contain"):
