programs.sol:
"""A lexical detector for parsing, with spelling-based false positives.

Parse words produce the strongest negative pulses. Split 'ars...' fragments
also respond, especially immediately after a token ending in p.
Validity, grammar and text-conversion vocabulary produce smaller pulses.
Case and identifier punctuation calibrate the response; other tokens are zero.
This predicts lexical signals, not whether the input is actually valid syntax.
"""
READS = ()

PARSE_FORMS = {
    'parse': 5.3,
    'parser': 5.6,
    'parsers': 4.2,
    'parsed': 3.8,
    'parsing': 4.8,
    'parses': 4.3,
}
PARSE_FRAGMENTS = {
    'pars': 3.6,
    'ars': 1.9,
    'arse': 2.1,
    'arsi': 1.3,
    'arsed': 0.5,
    'arsing': 1.5,
    'arser': 3.4,
    'arsers': 5.4,
}
VALIDITY = {'valid', 'invalid', 'validate', 'validity', 'isvalid'}
GRAMMAR = {'grammar', 'syntax', 'yntax', 'lexer', 'validation'}
VALIDATORS = {'validator', 'validators', 'validating', 'validates'}
CONVERSION = {'decode', 'decoding', 'decipher', 'fromstring', 'interpreter',
              'serialize', 'deserialize', 'unmarshal', 'marshal', 'stringify',
              'erialize', 'parseint', 'parsefloat', 'urlparse', 'argumentparser'}
INTERPRETATION = {'interpret', 'interpretation', 'interpretations', 'interpreting'}
EXTRACTION = {'extract', 'extraction', 'extractor', 'navigate', 'navigating'}
PROCESSING = {'travers', 'traverse', 'processing', 'extracted', 'interpreted'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-/\\(')
    lower = word.lower()
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]

    if lower in PARSE_FORMS:
        strength = PARSE_FORMS[lower]
        if (lower == 'parser' and token.startswith((' ', '-'))
                and word.islower()):
            strength = 4.7
        elif (lower == 'parsed' and word.islower()
              and not token.startswith((' ', '_'))):
            strength = 3.0
        if lower == 'parse' and token.startswith('.'):
            strength = 5.8
            if 'pars' in previous.lower():
                strength += 1.1
            elif previous.strip() == 'JSON':
                strength -= 1.0
        if token.startswith('('):
            strength *= 0.8
    elif lower in PARSE_FRAGMENTS:
        strength = PARSE_FRAGMENTS[lower]
        if lower == 'ars':
            if word.isupper():
                strength = 2.6
            elif word[0].isupper():
                strength = 1.3
        elif lower == 'pars' and token.startswith(' '):
            strength = 2.0 if word.islower() else 3.0
        if previous.lower().endswith('p'):
            if lower in {'arse', 'arser'}:
                strength = 4.5
            elif lower == 'arsed':
                strength = 4.1
            elif lower == 'arsing':
                strength = 6.5
    elif lower == 'mars':
        strength = 2.0 if word == 'Mars' else 1.5
    elif lower == 'sparse':
        strength = 1.4
    elif lower == 'argparse':
        strength = 2.9
    elif word in {'解析', 'ParseException'}:
        strength = 3.8
    elif lower in VALIDITY:
        strength = 1.1
    elif lower in GRAMMAR or lower in CONVERSION:
        strength = 0.95
    elif lower in VALIDATORS or lower in INTERPRETATION or lower in EXTRACTION:
        strength = 0.65
    elif lower in PROCESSING:
        strength = 0.4
    else:
        strength = 0.0
    return None, -strength

programs.haiku:
"""List-separator commas (layers.0.mlp.down_proj:2013).

What it does: this component goes strongly negative on the comma that closes a short
item in a running list ("pistols, rifles, knives, [,]", "Phoenix, Austin, Chicago, [,]"),
and on the "and"/"or" that follows such a comma ("..., gloves, and [and]"). Its
strength depends on how many items the list already has and on how long the item
just closed is:

- a list comma needs at least one earlier comma in the same sentence (so the first
  comma of a list, and commas after a whole clause such as "However," or "Wait,", get 0);
- the comma closing a one-word item gets about -1.0; each extra word in the item
  multiplies it by 0.6, so a comma after a long clause is close to 0;
- the "and"/"or" right after a list comma gets the same value as that comma;
- a sentence end (. ! ? ; : or a newline) starts a new sentence and clears the count.

Everything else is 0. The program only needs the newest token and a small carry
(comma count, tokens since the last comma, the pending comma value, the document id).

Main ideas: a comma-separated list of parallel items is the context in which this
component fires, and the firing is strongest when the item is a bare word or name.
"""

READS = ()

COMMAS = {",", "，", "、"}
CONJUNCTIONS = {"and", "or"}
SENTENCE_END = {".", "!", "?", ";", ":", "。", "！", "？", "；", "："}
BASE = 1.0  # activation of a list comma closing a one-word item
DECAY = 0.6  # factor per extra word in the closed item


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = dict(doc=doc, commas=0, gap=0, last=0.0, after_comma=False)
    gap = carry["gap"] + 1  # tokens since the last list comma, this token included
    value = 0.0
    if "\n" in tok or word in SENTENCE_END:
        new = dict(doc=doc, commas=0, gap=0, last=0.0, after_comma=False)
    elif word in COMMAS:
        if carry["commas"] >= 1 and gap >= 2:
            value = -BASE * DECAY ** (gap - 2)
        new = dict(doc=doc, commas=carry["commas"] + 1, gap=0, last=value, after_comma=True)
    elif word in CONJUNCTIONS and carry["after_comma"]:
        value = carry["last"]
        new = dict(doc=doc, commas=carry["commas"], gap=gap, last=0.0, after_comma=False)
    else:
        new = dict(doc=doc, commas=carry["commas"], gap=gap, last=0.0, after_comma=False)
    return new, value

programs.sol:
"""Approximate possessive apostrophes and s-ending word-piece boundaries.

Treat apostrophe-s as possession except after common contraction bases.
Bare apostrophes after plural-looking s endings get larger values; letters
continuing those endings get a weaker echo. Spelling, suffixes and case
control its size. Short quoted spans suppress apparent possessives, and
quotation marks get small boundary-dependent values. This deliberately
omits noun-specific strengths and diffuse background activations.
"""
READS: tuple[str, ...] = ()

CONTRACTIONS = frozenset('''
it that there he she let here what who where how when why
'''.split())
# Common function words and nonplural word stems that end in s.
NONPLURALS = frozenset('''
s dis mis trans res pres cons ins subs pos sens pass ass poss necess
as is has was his this its us yes thus
'''.split())
SUFFIXES = frozenset('''
ing ed ion ions ation ations ate ates ity ness ly es er ers est
'''.split())
PLACE_ENDINGS = frozenset('ville burg boro borough bury dorf ford'.split())


def plural_values(text):
    """Scores for an apostrophe and for a letter continuation after s."""
    word = text.strip().lower()
    if word in NONPLURALS:
        return 1.0, 0.0
    if not word.isalpha():
        return 1.0, 0.0
    if word.endswith(('ss', 'us', 'as', 'is', 'ous')):
        return 1.6, 0.05
    if word.endswith(('ers', 'ors', 'ies')):
        return 3.8, 0.55
    if word.endswith(('ms', 'ds', 'ls')):
        return 3.1, 0.65
    if word.endswith(('ts', 'ns', 'ks', 'ps', 'gs')):
        return 3.1, 0.45
    return 3.1, 0.3


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    quote_age = carry[2] if same_doc else -1
    word = previous.strip().lower()
    s_ending = previous.endswith(('s', 'S'))
    if text in ("'s", "'S", '’s', '’S'):
        if word in CONTRACTIONS:
            value = -0.27 if word in {'he', 'she'} else (
                -0.15 if word in {'it', 'that', 'there'} else 0.03)
        elif s_ending:
            value = 1.5
        elif word in {'children', 'men', 'women', 'people'}:
            value = 1.2
        elif word.isdigit():
            value = 0.68
        else:
            value = 0.88
    elif s_ending and text in ("'", '’', "\\'", '‘'):
        value = plural_values(previous)[0]
        if 0 <= quote_age <= 6:
            value *= 0.3
    elif s_ending and text and text[0].isalpha():
        value = plural_values(previous)[1]
        lower = text.lower()
        if lower in PLACE_ENDINGS:
            value += 0.3
        if len(text) == 1:
            value += 0.2
        if lower in SUFFIXES or text.startswith(('s', 'S')):
            value -= 0.25
        if text[0].isupper():
            value *= 0.2
        if value > 0.0:
            value *= 1.4
    elif text in (' “', ' ‘'):
        value = 0.19
    elif text == ' "':
        value = 0.13 if previous and previous[-1].isalnum() else 0.03
    elif text == '“':
        value = -0.14 if previous and previous[-1].isalpha() else 0.14
    else:
        value = 0.0
    # Only short quoted fragments are likely to be closing quotes, not genitives.
    if text in ("'", '’') and quote_age >= 0:
        quote_age = -1
    elif text.endswith(("'", '‘')) and (
            not previous or not previous[-1].isalnum() or text[:1].isspace()):
        quote_age = 0
    elif quote_age >= 0:
        quote_age += 1
        if quote_age > 6:
            quote_age = -1
    return (doc, text, quote_age), float(value)

programs.haiku:
"""Possessive-marker detector for layers.0.mlp.down_proj:2016.

The component fires on the token that marks a possessive, in two forms:

* "'s" / "’s" after a noun ("the dog's bone", "Ohio's needs"): about 0.5-1.0.
* A bare apostrophe after a plural noun ending in s ("the residents' homes",
  "Board of Veterans' Appeals", "Defendants’ motion"): about 2.5-3, the strongest.

It stays near zero on contractions after pronouns or "let/there/that" (it's, that's,
let's, there's, he's), where "'s" means "is" or "has", and on other apostrophes
(n't, l'/d', quote marks in code).

Predictions are fixed class values: the program is a readable rule, not a lookup table.
"""

READS = ()

# tokens before "'s" where it is a contraction ("it's", "that's"), not a possessive
CONTRACTION_HOSTS = {
    "it", "that", "he", "she", "let", "there", "here", "what", "who",
    "where", "how", "this", "everything", "something", "nothing",
}
POSSESSIVE_S = {"'s", "’s", "'S"}
APOSTROPHES = {"'", "’"}

POSSESSIVE_S_VALUE = 0.8  # "'s" after a noun
PLURAL_POSSESSIVE_VALUE = 2.5  # bare apostrophe after a word ending in s


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if token in POSSESSIVE_S:
        value = 0.0 if prev in CONTRACTION_HOSTS else POSSESSIVE_S_VALUE
    elif token in APOSTROPHES and prev.endswith("s"):
        value = PLURAL_POSSESSIVE_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A local English relative-clause/question signal, not a general parser.

Copulas, subject pronouns, and several common predicates are positive after
clause openers; modifiers and modal auxiliaries are mostly negative. The
response depends on both words: "what is" is stronger than "that is".
An opener can also influence a copula across one intervening auxiliary or
adverb. Capitalized "Which"/"That", document-initial question words, and a
few fixed phrases get explicit adjustments (including plural "FIG S").
Unrecognized continuations use a small opener-specific default; elsewhere
the prediction is zero except for the listed phrase and "means" rules.
State resets at document boundaries.
"""
import re

READS = ()
# Copula, 'it', 'the', modifier, modal, unrecognized continuation.
OPENERS = {
    'what': (2.01, 1.95, .89, -1.62, -1.23, -.19),
    'which': (1.78, 1.25, .32, -.80, -.13, .12),
    'how': (1.74, 1.66, 1.13, -.90, -.62, -.09),
    'who': (1.01, .51, .05, -.90, -.65, .04),
    'that': (.91, .44, .02, -.78, -.19, -.03),
    'where': (.80, .67, .15, -1.09, -1.41, -.12),
    'why': (.83, .81, .48, -.92, -1.01, -.13),
    'when': (.80, .52, .00, -.80, -.48, -.02),
    'whether': (.68, .59, .28, -.62, -.27, -.02),
    'if': (.54, .38, .12, -.48, -.21, -.01),
    'because': (.50, .35, .10, -.35, -.18, -.02),
}
PRONOUNS = {
    'they': (.52, -.06), 'he': (.26, -.08), 'she': (.26, -.08),
    'this': (.52, -.18), 'that': (.91, -.13), 'i': (0., -.14),
    'you': (.24, -.08), 'we': (.20, -.10),
}
MODIFIERS = set(
    'all both one two three no none some most any each every few '
    'also only even just not more further first last recently usually '
    'in of on at by for with from or'.split()
)
DEGREE = set(
    'other else others additional extra better best far long big small '
    'large little easy old well simple specific particular'.split()
)
PREDICATES = set(
    'means meant constitutes consists consisted follows happens happened '
    'occurs occurred'.split()
)
RELATIONS = set(
    'contains includes included include makes causes implies represents '
    'requires encompasses comprises equals matches needs wants appears '
    'making getting having considering'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    raw_previous, raw_earlier = ('', '') if start else carry[1:]
    previous, earlier = raw_previous.lower(), raw_earlier.lower()
    raw_word = prefix.token_strings[-1].strip()
    word = raw_word.lower()
    value = 0.
    if previous in OPENERS:
        copula, subject, article, modifier, modal, value = OPENERS[previous]
        if word in {'is', 'isn'}:
            value = copula
        elif word in {'are', 'aren', 'was', 'were'}:
            value = .73 * copula + .10
        elif word in {"'s", '’s'}:
            value = .30 * copula
        elif word == 'it':
            value = subject
        elif word == 'the':
            value = article
        elif word in PRONOUNS:
            scale, offset = PRONOUNS[word]
            value = scale * subject + offset
        elif word in {'its', 'their', 'your', 'my', 'our', 'his', 'her'}:
            value = .34 * subject - .12
        elif word in {'can', 'could', 'may', 'might', 'must', 'will',
                      'shall', 'should'}:
            value = modal
        elif word in {'would', 'wouldn'}:
            value = .7 * modal + .14
        elif word in {'do', 'did', 'don', 'didn'}:
            value = .79 * modal + .13
        elif word in {'does', 'doesn', 'have', 'has', 'had'}:
            value = .16 * copula - .15
        elif word in {"'d", '’d', "'ll", '’ll'}:
            value = -1.
        elif word in PREDICATES:
            value = .75 * copula + .10
        elif word in RELATIONS:
            value = .37 * copula + .05
        elif word in DEGREE:
            value = 1.4 * modifier
        elif word in MODIFIERS:
            value = modifier
        elif word in {'a', 'an'}:
            value = .49 * article - .14
        elif word in {'if', 'when'}:
            value = 1.2 * copula - .78
        elif word == 'about':
            value = copula - .10
        elif word == 'to':
            value = .24 if previous == 'how' else -.25
        elif word == ',':
            value = .26 * modifier - .33
        elif word in {'many', 'much'}:
            value = -.15 if previous == 'how' else .7 * modifier
        if previous == 'which' and word == 'of':
            value = -.05 if raw_previous == 'Which' else -.6
        if previous == 'what' and word == 'kind':
            value = -2.45
        if word in {'is', 'are', 'was', 'were'}:
            if raw_previous == 'Which':
                value += .4
            elif raw_previous == 'That':
                value += .17
            if raw_word == 'Is':
                value += .75
    elif (earlier in OPENERS and word in {'be', 'is', 'are', 'was'}
          and previous in {'can', 'could', 'might', 'will', 'would', 'may',
                           'must', 'should', 'also', 'indeed', 'just'}):
        value = .4 * OPENERS[earlier][0]
    elif start and word in {'what', 'how', 'which'}:
        value = {'what': 2.7, 'how': 2.4, 'which': 1.55}[word]
    elif previous in {'think', 'thinking', 'thought'} and word == 'about':
        value = 1.05
    elif previous == 'fig' and raw_word == 'S':
        value = .8
    elif (previous in {'no', 'any', 'some', 'something', 'anything'}
          and word in {'other', 'else', 'further', 'additional'}):
        value = -.8 if previous == 'no' else -.5
    elif word == 'means':
        value = .40
    elif (earlier in {'what', 'which'} and word == 'of'
          and previous in {'kind', 'kinds', 'type', 'sort', 'one'}):
        if earlier == 'which':
            value = -.95
        else:
            value = -2.3 if previous == 'kind' else -1.5
    match = re.search(r'([^\W\d_]+)$', raw_word)
    latest = match.group(1) if match else raw_word
    return (doc, latest, raw_previous), float(value)

programs.haiku:
"""Option-word detector for layers.0.mlp.down_proj:2019.

The component writes a large positive signal into the residual stream whenever the
current token is the word "option", in prose, in code identifiers and in abbreviations:
option, Options, .options, _option, getOption, opt, optarg, optional, and 选项.
The plain word "option"/"options" is strongest. Words of the same family, in
command-line and settings code, get a weaker but clear response: flag(s), arg(s),
argv, kwargs, mode, setting(s), choice(s), "alternative(ly)", "possibility".
Chinese 往 ("toward", as in 往前, 以往, 前往) and past-tense words push it negative.
"""

READS = ()

RELATED = {
    "flag", "flags", "arg", "args", "argv", "argc", "kwargs", "nargs", "argument", "arguments",
    "mode", "modes", "setting", "settings", "choice", "choices", "alternative", "alternatively",
    "alternate", "possibility", "possibilities",
}
OPT_ABBREV = {"opt", "opts", "optarg", "getopt"}
PAST = {"past", "过去", "过去的", "过去了", "过往"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().strip("._-(,$?=[\t'\"").lower()
    if raw.strip() == "往":
        return None, -8.0
    if "往" in raw:
        return None, -3.0
    if word in ("option", "options"):
        return None, 3.5
    if "option" in word or "选项" in raw:
        return None, 2.5
    if word in OPT_ABBREV:
        return None, 2.5
    if word in RELATED:
        return None, 1.0
    if word in PAST:
        return None, -1.0
    return None, 0.0

programs.luna:
"""Respond to words about choosing among options and setting parameters."""
import re

READS = ()

OPTIONS = {"option", "options"}
ARGUMENTS = {"argument", "arguments", "arg", "args", "kwargs"}
CHOICES = {
    "choice", "choices", "alternative", "alternatives", "alternate",
    "possibility", "possibilities", "wahl", "choix", "选择",
}
SETTINGS = {"mode", "modes", "setting", "settings", "default", "defaults"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    words = re.findall(r"[^\W_]+", token)
    if "option" in words or "options" in words:
        return None, 3.4
    if "opts" in words:
        return None, 2.2
    if "optional" in words:
        return None, 2.3
    if "opting" in words:
        return None, 1.6
    if any(word in ARGUMENTS for word in words):
        return None, 0.8
    if "flag" in words or "flags" in words:
        return None, 1.2
    if any(word in CHOICES for word in words):
        return None, 0.6
    if any(word in SETTINGS for word in words):
        return None, 0.65
    if "--" in token:
        return None, 0.45
    if "past" in words:
        return None, -0.8
    return None, 0.0

programs.sol:
"""Conservative, partial lexical approximation of this weak component.

Lowercase whole-word classes get small signed levels: counting/distribution and
requirements are negative; types, definitions and expected results are positive.
Adjacent-word rules handle selected English constructions. Identifier spelling
adds negative levels for database/form configuration names. Explicit structure
markers, contractions and two Japanese particles have separate levels.

Use half-strength predictions because these classes omit substantial contextual
variation. Unrecognized tokens get zero. Remember only the preceding token,
and forget it at each document boundary. This is not a unified semantic detector.
"""

import re

READS = ()

# Each group is an ordinary word class; spelling, not token IDs, is used.
WORD_GROUPS = (
    (-0.032, 'two three four five six seven eight nine ten number numbers'),
    (-0.042, 'each every either neither several'),
    (-0.074, 'together pair pairs'),
    (-0.090, 'require requires'),
    (-0.042, 'required requirement need should'),
    (-0.036, 'true false null none'),
    (-0.023, 'only again without into between among'),
    (-0.070, 'past once started'),
    (-0.080, 'administrative police political society'),
    (-0.064, 'detect detected detection'),
    (0.055, 'expected expecting expect desired actual'),
    (0.043, 'type types class classes'),
    (0.059, 'meaning means definition definitions description descriptions'),
    (0.036, 'define defined'),
    (0.050, 'half portion portions amount parts'),
    (0.022, 'one single another'),
    (0.045, 'count counts counting multiple'),
    (0.044, 'try tries'),
    (0.048, 'else outside exit out'),
    (0.050, 'standard general'),
    (0.040, 'everything completely'),
    (0.014, 'will must'),
    (-0.018, 'was were are'),
    (0.027, 'them those others'),
    (-0.019, 'your'),
)
WORD_VALUES = {
    word: value
    for value, words in WORD_GROUPS
    for word in words.split()
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    w = s.strip()
    prev = previous.strip().lower()
    value = 0.0

    # Whitespace-prefixed words distinguish whole words from attached fragments.
    if s.startswith(' ') and s[1:].isalpha() and s[1:].islower():
        value = WORD_VALUES.get(w, 0.0)
        if w == 'to':
            if prev in {'try', 'tries', 'tried', 'trying'}:
                value += 0.085
            elif prev in {'need', 'needs', 'want', 'wants', 'willing', 'have'}:
                value += 0.049
            elif prev in {'go', 'went', 'returned', 'managed'}:
                value += 0.075
            elif prev in {'known', 'enough', 'sure', 'connected'}:
                value -= 0.080
        elif w == 'of':
            if prev in {'number', 'numbers', 'pair', 'pairs', 'list', 'array'}:
                value -= 0.050
            elif prev in {'knowledge', 'proof', 'detection', 'symptoms'}:
                value -= 0.100
            elif prev in {'level', 'levels', 'degree', 'power'}:
                value -= 0.075
            elif prev in {'all', 'most', 'fraction', 'subset', 'snippet'}:
                value += 0.080
            elif prev in {'meaning', 'terms', 'direction', 'derivative', 'way'}:
                value += 0.065
            elif prev in {'country', 'republic'}:
                value -= 0.050
        elif w == 'the' and prev == 'all':
            value = 0.078
        elif w == 'is':
            if prev in {'this', 'what', 'here', 'answer'}:
                value = 0.035
            elif prev == 'there':
                value = -0.033
        elif w == 'are':
            if prev in {'they', 'who'}:
                value = -0.052
            elif previous.strip() == 'We':
                value = 0.027
    elif len(s) == 1 and s.isascii() and s.isdigit():
        value = -0.002 if s == '1' else 0.0 if s == '0' else 0.003

    # Database/form configuration names are more negative inside identifiers.
    parts = tuple(p.lower() for p in re.findall(
        r'[A-Z]+(?=[A-Z][a-z]|[^A-Za-z]|$)|[A-Z]?[a-z]+', s
    ))
    identifier = not s.startswith(' ') or len(parts) > 1
    roots = set(parts)
    if roots & {'admin', 'locale', 'currency', 'workflow'}:
        value = -0.12
    elif 'language' in roots:
        value = -0.035 if not identifier else -0.14
    elif 'settings' in roots:
        value = -0.05 if not identifier else -0.10
    elif 'meta' in roots:
        value = -0.25 if s.startswith('_') else -0.10
    elif identifier:
        if roots & {'field', 'fields'}:
            value = -0.22 if len(parts) > 1 else -0.14
        elif 'parent' in roots:
            value = -0.22 if len(parts) > 1 else -0.105
        elif roots & {'filter', 'filters'}:
            value = -0.025 if s.startswith('.') else -0.10
        elif 'template' in roots:
            value = -0.11 if 'Template' in s else -0.045
        elif 'page' in roots and roots & {'per', 'size', 'current'}:
            value = -0.25
        elif roots & {'page', 'pages'} and s[:1] in {'_', '.', '$'}:
            value = -0.08
        elif roots & {'view'} and len(parts) == 1:
            value = 0.0 if s.startswith('.') else -0.07
        elif 'order' in roots and 'by' in roots:
            value = -0.30
    if 'error' in roots:
        value = -0.04
        if roots & {'type', 'value', 'key', 'import'} or s.startswith('.'):
            value = -0.09
    elif 'stream' in roots and len(parts) == 1:
        value = -0.04
    if s == 'PASS':
        value = 0.13

    if s == '</think>':
        value = -0.207
    elif s == '<tool_response>':
        value = -0.055
    elif s == '__':
        value = -0.053
    elif s == '://':
        value = -0.092
    elif w == '✓':
        value = 0.084
    elif s in {'’t', "n't"}:
        value = 0.048
    elif s == '’s':
        value = 0.025
    elif s == 'は':
        value = -0.054
    elif s == 'を':
        value = 0.057
    elif s == 'package' and (carry is None or carry[0] != doc):
        value = -0.325

    return (doc, s), float(0.5 * value)

programs.luna:
"""Long token spellings carry a slightly higher activation on average."""

