HTML_TAGS = set('''a b i p em strong span div code pre sub sup td tr th table body
    html head title li ul ol br img script style link input button form label
    section h1 h2 h3 h4 h5 h6 summary details font tt'''.split())
COMMON_TYPES = set('''int float double char string String Integer Double Long
    Boolean Object bool Byte byte short Short T U V W size_t ptrdiff_t wchar_t
    char16_t char32_t mutex recursive_mutex timed_mutex shared_mutex'''.split())
OTHER_TYPES = set('''void any unknown never undefined object number
    boolean str'''.split())
MARKS = {'≥': -0.65, '≧': -0.65, '⟩': 1.8, '〉': 1.8, '≫': 1.8,
         '||': 0.48, '<<': 0.3, ']]': 0.4}


def right_angle(recent, s):
    # Match delimiters, excluding compound operators such as <= and ->.
    stack = []
    for i, text in enumerate(recent):
        for op in ('<<', '<=', '<-', '->', '=>', '>='):
            text = text.replace(op, ' ' * len(op))
        for j, c in enumerate(text):
            if c == '<':
                stack.append((i, j))
            elif c == '>' and stack:
                stack.pop()
