        i, j = stack[-1]
        body = recent[i][j + 1:] + ''.join(recent[i + 1:])
        name = body.replace('<', '').replace('>', '').strip()
        name = re.sub(r'\\+(?=[A-Z/])', '', name).rstrip('\\')
        words = re.findall(r'\w+', name)
