        return -0.4 if '>=' in token else 0.4
    if s.startswith(' '):
        if '\n' in s:
            return max(0.1, value * 0.3)
        type_like = distance < 6 or nested or attached
        return value * 0.8 if value > 0 and type_like else -1.3
    suffix = token.lstrip('>')
    if not suffix:
        return value + (0.6 if token == '>>' and value > 0 else 0.0)
    if not token.startswith('>'):
        return max(0.0, value) * 0.6 if token.startswith(('[]', '*')) else 0.7
    if '\n' in suffix:
        factor = 0.25 if suffix.count('\n') > 1 else 0.45
        if suffix.startswith('();'):
