backslash-n and backslash-t escapes form a separate positive response,
including split escapes; common LaTeX n-commands are excluded. All other
current tokens return zero. Two previous tokens are retained, resetting at
document boundaries. This deliberately omits weaker vocabulary-specific effects.
"""
READS = ()

# Regular inflections are recognized from these familiar verb families.
POSSESSION = {'have', 'own', 'possess', 'lack'}
PROVISION = {'give', 'provide', 'furnish', 'supply', 'deliver'}
CREATION_ACQUISITION = {
    'make', 'create', 'establish', 'offer', 'get', 'receive', 'obtain',
    'gain', 'acquire', 'adopt',
}
OBJECT_VERBS = {
    'find', 'take', 'need', 'require', 'write', 'add', 'build', 'develop',
    'generate', 'produce', 'maintain', 'contain', 'buy', 'draw',
    'issue', 'earn', 'yield', 'carry', 'bring', 'pose', 'suffer',
}
OTHER_OBJECT_VERBS = {
    'show', 'see', 'include', 'represent', 'form', 'feature', 'share',
    'play', 'do', 'put', 'construct', 'present', 'constitute', 'comprise',
    'perform', 'publish', 'want', 'remain', 'choose', 'return',
}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
TRANSITION_USE = {'become', 'use'}
FOREIGN_FUNCTION_WORDS = {
    'de', 'di', 'en', 'y', 'e', 'que', 'qui', 'sin', 'pour', 'para',
    'per', 'dans', 'du', 'des', 'und', 'der', 'die', 'das', 'zu',
    'von', 'avec', 'sur', 'et', 'ou', 'o', 'pentru',
}
# These n-initial commands are mathematics/markup, not newline escapes.
LATEX_N_COMMANDS = {
    'new', 'nu', 'ne', 'neq', 'neg', 'not', 'nabla',
    'node', 'nonumber', 'nocite',
}
VERBS = (POSSESSION | PROVISION | CREATION_ACQUISITION | OBJECT_VERBS
         | OTHER_OBJECT_VERBS | TRANSITION_USE)
IRREGULAR = {
    'has': 'have', 'had': 'have', 'having': 'have',
    'gave': 'give', 'given': 'give', 'made': 'make',
    'got': 'get', 'getting': 'get', 'found': 'find',
    'took': 'take', 'taken': 'take', 'wrote': 'write', 'written': 'write',
    'built': 'build', 'bought': 'buy', 'drew': 'draw', 'drawn': 'draw',
    'saw': 'see', 'seen': 'see', 'did': 'do', 'done': 'do',
    'putting': 'put', 'brought': 'bring', 'became': 'become',
    'chose': 'choose', 'chosen': 'choose',
}


def verb_root(word):
    if word in IRREGULAR:
        return IRREGULAR[word]
    if word in VERBS:
        return word
    candidates = []
    if word.endswith('s'):
        candidates.extend((word[:-1], word[:-2]))
    if word.endswith('ies'):
        candidates.append(word[:-3] + 'y')
    if word.endswith('ed'):
        candidates.extend((word[:-2], word[:-1], word[:-3]))
    if word.endswith('ing'):
        candidates.extend((word[:-3], word[:-3] + 'e', word[:-4]))
    for candidate in candidates:
        if candidate in VERBS:
            return candidate
    return word


def article_context(previous, before_previous):
    # Approximate the grammatical role in which an indefinite phrase starts.
    word = previous.strip().lower()
    root = verb_root(word)
    inflection = 0.0
    if word != root:
        if word.endswith('ing'):
            inflection = -0.10
        elif word.endswith('ed') or word in IRREGULAR:
            inflection = 0.15
        elif word.endswith('s'):
            inflection = 0.08
    if not previous:
        return -0.08
    if root in POSSESSION:
        return 2.45 if root == 'have' else 1.9
    if root in PROVISION:
        return 2.24 + inflection
    if root in CREATION_ACQUISITION:
        return 2.04 + inflection
    if root in OBJECT_VERBS:
        return 1.68 + inflection
    if root in OTHER_OBJECT_VERBS:
        return 1.32 + inflection
    if word in {'there', 'exist', 'exists'}:
        return 2.4
    if word in COPULAS or word in {"'s", '’s'}:
        if before_previous.strip().lower() == 'there':
            return 2.3
        if word in {"'s", '’s'}:
            return 1.05
        return 1.39 if word in {'was', 'been'} else 1.27
    if root in TRANSITION_USE:
        return 1.03
    if word == 'with':
        return 1.28
    if word == 'without':
        return 1.63
    if word in {'as', 'like'}:
        return 0.88
    if word in {'of', 'in', 'on', 'during', 'between'}:
        return -0.32 if previous.strip()[:1].isupper() else -0.1
    if word in {'from', 'at', 'over', 'across', 'within', 'around', 'near'}:
        return 0.04
    if word == 'to':
        return 0.30
    if word in {'about', 'under', 'that', 'if', 'when', 'where',
                'which', 'then', 'what'}:
        return 0.2
    if word in {'by', 'into', 'through', 'after', 'against', 'upon', 'via'}:
        return 0.47
    if word in {'for', 'up'}:
        return 0.65
    if word in {'and', 'or', 'but', 'than'}:
        return 0.31
    if word in {'such', 'not', 'just', 'only', 'also', 'still', 'quite'}:
        return 1.12
    if word in {'you', 'me', 'him', 'her', 'us', 'it', 'this'}:
        return 1.0
    if word in FOREIGN_FUNCTION_WORDS:
        return -0.23
    if word in {'the', 'all', 'since', 'so'}:
        return -0.06
    if not any(c.isalpha() for c in word):
        return -0.16 if any(c in word for c in ',;:=') else -0.02
    if any(c in word for c in '\\_$<>='):
        return -0.1
    if not word.isascii():
        return 0.0
    if len(word) == 1:
        return 0.0
    return 0.12 if not previous.startswith(' ') else 0.62


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before_previous = ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in {' a', ' an'}:
        value = article_context(previous, before_previous)
    elif token in {' some', ' another', ' one', ' two', ' three',
                   ' several', ' additional', ' multiple', ' something'}:
        context = article_context(previous, before_previous)
        if token in {' some', ' another'}:
            value = 0.44 * context - 0.15
        elif token in {' additional', ' several', ' multiple'}:
            value = 0.3 * context
        else:
            value = 0.28 * context - 0.12
    elif token in {' A', ' An'}:
        value = 0.12 if previous.rstrip().endswith(('.', '?', '!')) else 0.0
    elif token == '\\n':
        value = 0.9 if previous.strip().isdigit() else 1.06
        if previous in {'\\n', '\\t'}:
            value = 1.16
        elif previous == 'n' and before_previous.endswith('\\'):
            value = 1.28
    elif token == '\\t':
        value = 0.87
    elif (previous.endswith('\\') and
          (token == 't' or (token.startswith('n') and
           token not in LATEX_N_COMMANDS))):
        if token[0] == 'n':
            value = 1.66 if len(token) == 1 else 0.95
        else:
            value = 0.55
        if previous.endswith('\\\\'):
            value *= 0.7
    return (doc, token, previous), float(value)

