"""Recognize article-like words and code's visible escaped-newline markers."""

READS = ()

INDEFINITE_WORDS = {" another", " one", " una"}


def step(carry, prefix, upstream):
    """Approximate article activations and the pulse on escaped newlines."""
    del carry, upstream
    token = prefix.token_strings[-1]
    if token == " a":
        return None, 0.91
    if token == " an":
        return None, 1.19
    if token in INDEFINITE_WORDS:
        return None, 0.45
    if token == "\\n":
        return None, 0.74
    if (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    ):
        previous = prefix.token_strings[-2]
        if previous.endswith("\\") and token.startswith("n"):
            return None, 1.26
    return None, 0.0

programs.haiku:
"""Negation-scope detector for layers.0.mlp.down_proj:2035 (program v5).

What the component does: it reads the word right after a negation ("not", "n't", "never",
"cannot", "dont", or a foreign equivalent such as 不 / nicht / не / không) and writes a
signed signal into the residual stream:
  * positive when that word continues the negated verb phrase with an auxiliary, infinitive
    marker, or determiner ("does not [need]", "should not [be]", "not [to]", "not [a]"),
    strongest right after the negator;
  * negative when that word is a predicate adjective or limiting word completing the negation
    ("not [clear]", "not [sure]", "not [enough]", "not [only]", "not [yet]", "not [able]").
Two words after a negator the same rules apply more weakly ("does not want [to]").
Outside negation, "be" and "been" are mildly positive, most after modals and "to" ("will be",
"to be", "has been") and near zero after can/may. Everything else is 0.
"""

NEGATORS = {" not", "not", "n't", "’t", " never", " cannot", " dont", "不", "没有", " nicht", " не", " không"}
MODALS = {" will", " would", " must", " should", " shall", " to", " has", " have", " had", " also"}
WEAK_MODALS = {" can", " may", " could", " might"}
INTENT = {" want", " wanted", " going", " have", " need", " trying", " unable", " refused", " intended", " tried"}
CONTINUES = {" be", " been", " to", " have", " need", " use", " do", " go", " going", " too", " so",
             " a", " an", " the", " in", " as", " that"}
COMPLETES = {" clear", " sure", " enough", " only", " yet", " able", " always", " sufficient",
             " obvious", " straightforward", " difficult", " easy", " known", " even", " quite",
             " really", " know", " understand", " properly", " without", " null", " necessarily"}

READS = ()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    t = prefix.position
    cur = strings[t]
    docs = prefix.document_ids

    def back(k):
        # the token k places earlier, or None if it is before this document starts
        i = t - k
        if i < 0 or docs[i] != docs[t]:
            return None
        return strings[i]

    if back(1) in NEGATORS:
        if cur in CONTINUES:
            return carry, 2.0
        if cur in COMPLETES:
            return carry, -1.5
        return carry, 0.4
    if back(2) in NEGATORS:
        if cur in CONTINUES:
            return carry, 1.0
        if cur in COMPLETES:
            return carry, -1.3
        return carry, 0.0
    if cur in {" be", " been"}:
        if back(1) in WEAK_MODALS:
            return carry, 0.1
        return carry, 0.55 if back(1) in MODALS else 0.4
    if cur == " to" and back(1) in INTENT:
        return carry, 0.5
    return carry, 0.0

programs.luna:
"""Approximate a rare pulse on non-finite forms of English "be".

The harvest's strong examples are "be", "been", and "being" after a modal,
negation, or infinitive/auxiliary cue; finite forms are left alone.
"""

READS = ()

NONFINITE_BE = {"be", "been", "being"}
LEAD_INS = {
    "not", "to", "have", "has", "had", "should", "would", "will",
    "shall", "must", "can", "cannot", "can't", "could", "may", "might",
    "ever", "'d",
}


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().casefold()
    if current not in NONFINITE_BE or len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2].strip().casefold()
    return None, 0.55 if previous in LEAD_INS else 0.0

programs.sol:
"""Approximate a lexical response to short English complement constructions.

The strongest response is positive on 'to do', especially after necessity,
desire, or an indefinite pronoun; 'to find/become' are strongly negative.
Other infinitives have weaker, word-dependent signs. There are also responses
on modal + do, necessity + to/by/for, preposition + which/whom, and too much.
Chat delimiters and document-initial ' to' get fixed responses.
Rules match lowercased, whitespace-prefixed token text, not a full parser.
Unlisted constructions get zero; diffuse small responses are not explained.
Only the previous two tokens are retained, resetting at each document.
"""
READS = ()

POSITIVE_INFINITIVES = set('''
make keep protect prevent say know change try move pay tell continue
perform follow add reduce improve achieve
'''.split())
NEGATIVE_INFINITIVES = set('''
have understand see include work reach meet think look offer
serve describe state design
'''.split())
STRONG_INFINITIVES = {
    'find': -0.77, 'become': -0.59, 'face': -0.82,
    'note': -0.52, 'mention': -0.55, 'mind': -0.76,
    'love': -0.67, 'own': -0.78, 'plan': -0.54,
    'match': -0.46, 'feel': -0.42, 'cause': -0.37,
    'go': 0.31, 'avoid': 0.36, 'buy': 0.39, 'fix': 0.40,
    'take': 0.10, 'use': -0.15, 'help': -0.15, 'show': -0.13,
}
NECESSITY = {'have', 'has', 'had', 'need', 'needs'}
DESIRE = {'want', 'wants'}
INDEFINITE_PRONOUNS = {'nothing', 'anything', 'everything', 'something'}
MODAL_DO = {
    'can': 0.68, 'cannot': 0.87, 'must': 0.65,
    'could': 0.50, 'should': 0.50, 'may': 0.28,
    'might': 0.28, 'will': 0.30, 'would': 0.27,
}
PREPOSITIONS = {'in', 'on', 'at', 'of', 'for', 'from', 'by', 'with'}
DELIMITERS = {
    '<think>': 0.225, '</think>': -0.12, '<|im_end|>': 0.048,
    '<tool_call>': 0.061, '</tool_call>': 0.062,
}


def after_to(word, governor):
    if word == 'do':
        if governor in NECESSITY:
            return 1.55
        if governor in DESIRE:
            return 1.47
        if governor == 'wanted':
            return 1.80
        if governor in INDEFINITE_PRONOUNS:
            return 1.63
        if governor in {'how', 'thing', 'things'}:
            return 1.43
        if governor in {'way', 'ways', 'trying', 'willing'}:
            return 1.33
        return 1.10
    if word == 'find':
        if governor in NECESSITY or governor == 'how':
            return -0.63
        if governor in {'able', 'unable', 'seem', 'seems'}:
            return -0.48
        if governor in {'trying', 'try'}:
            return -1.03
    if word == 'be':
        if governor in NECESSITY or governor == 'supposed':
            return 0.24
        if governor in {'required', 'needed'}:
            return 0.46
        if governor in DESIRE or governor in {'going', 'meant', 'intended'}:
            return 0.17
        if governor in {'found', 'shown', 'proved', 'prove', 'tend'}:
            return -0.13
    if word in POSITIVE_INFINITIVES:
        return 0.22
    if word in NEGATIVE_INFINITIVES:
        return -0.25
    if word in {'your', 'their', 'its'}:
        return -0.31
    if word in {'my', 'our', 'his', 'her', 'a'}:
        return -0.15
    return {
        'whom': 1.10, 'which': 0.68, 'those': -0.22, 'the': 0.028,
        'many': 0.50, 'much': 0.81, 'each': 0.17, 'you': 0.17,
    }.get(word, STRONG_INFINITIVES.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, governor = ('', '') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = DELIMITERS.get(token, 0.0)
    if token[:1].isspace():
        if fresh and token == ' to':
            value = 0.564
        elif previous == 'to':
            value = after_to(word, governor)
        elif word == 'do':
            value = MODAL_DO.get(previous, 0.0)
            if previous in {'i', 'you', 'we', 'they', 'who'}:
                value = 0.18
            elif previous in {"'t", '’t'}:
                value = 0.22
                if governor == 'can':
                    value = 0.60
                elif governor == 'couldn':
                    value = 0.50
            elif previous == 'not':
                value = 0.33 if governor == 'could' else 0.14
        elif token == ' find':
            value = -0.37 if previous in {'can', 'cannot', 'could'} else -0.16
        elif word == 'much':
            value = 0.57 if previous == 'too' else 0.12
        elif word in {'to', 'by', 'for'}:
            if previous == 'required':
                value = {'to': 0.48, 'by': 0.90, 'for': 0.39}[word]
            elif previous in {'needed', 'necessary'}:
                value = 0.42 if previous == 'needed' else 0.28
            elif word == 'to' and previous == 'order':
                value = 0.19
        elif word in {'which', 'whom'} and previous in PREPOSITIONS:
            value = 0.17 if word == 'which' else 0.40
        elif word == 'out' and previous in {'seek', 'seeking', 'find'}:
            value = -0.40
    return (doc, word, previous), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2036: the bare verb after the word "to".

What it responds to: the word right after an infinitive "to" (or a relative
"to which / to whom"). Its sign depends on the kind of verb:

- "to do" (and "has to do with", "nothing to do with") is strongly positive.
- "to find" is strongly negative.
- Other action / goal verbs after "to" (fix, avoid, prevent, protect, buy, go,
  keep, try, ...) are mildly positive.
- Perception / cognition / information verbs after "to" (understand, see, show,
  think, note, identify, ...) are mildly negative.
- Everything else (determiners such as "to a", "to the", nouns, other verbs)
  is about 0.

It is zero everywhere else, so it is silent on most tokens, as the component is.
"""

READS = ()

# Words after "to" that the component reads.
DO_VERB = {" do"}
FIND_VERB = {" find", " Find"}
RELATIVE = {" which", " whom"}  # "to which", "to whom"
ACTION_VERBS = {
    " fix", " repair", " avoid", " prevent", " protect", " comply", " accomplish",
    " buy", " pay", " change", " keep", " continue", " proceed", " go", " try",
    " obey", " preserve", " minimize", " maximize", " install", " simplify",
    " follow", " move", " prepare", " say", " tell", " pursue", " endure",
}
PERCEPTION_VERBS = {
    " understand", " note", " mention", " identify", " detect", " recognize",
    " see", " feel", " uncover", " discover", " analyze", " describe", " comment",
    " inquire", " think", " realise", " remember", " imagine", " show", " write",
    " highlight", " indicate", " present", " look", " know", " determine",
    " assess", " evaluate", " expect", " become",
}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    same_doc = len(prefix.document_ids) >= 2 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if len(tokens) < 2 or tokens[-2] != " to" or not same_doc:
        return carry, 0.0
    word = tokens[-1]
    if word in DO_VERB:
        value = 1.2
    elif word in FIND_VERB:
        value = -0.7
    elif word in RELATIVE:
        value = 0.8
    elif word in ACTION_VERBS:
        value = 0.3
    elif word in PERCEPTION_VERBS:
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

