programs.sol:
"""Approximate a negative response to separately tokenized sentence full stops.

The preceding token's letters, length and case set the strength: full lower-case
word tokens are strongest; numbers, initials and abbreviations are weak.
Word suffixes and hyphenated endings get intermediate or word-like strengths.
For 。, kana and Han-character endings receive different strengths. Punctuation
fused with quotes, parentheses or newlines has its own smaller response.
Ellipses, commas and colons get small positive responses; other tokens are zero.
No earlier document is consulted.
"""
READS = ()
ABBREVIATIONS = frozenset((
    'mr mrs ms dr prof st jr sr co inc ltd fig eq no vol pp vs etc al '
    'approx resp supra cir hon jan feb mar apr jun jul aug sep sept oct nov dec'
).split())
SHORT_FUNCTION_WORDS = frozenset((
    'it me us he we you him her them up so too do go be to on of by is as or'
).split())
WORD_SUFFIXES = frozenset((
    's es ed ers ies ing tion ions ation ations ment ments ness ity ities'
).split())


def word_strength(previous):
    word = previous.strip()
    n = len(word)
    if not word:
        return 0.0
    if '.' in word:
        return -0.1
    if (word.lower() in ABBREVIATIONS
            and (previous[:1].isspace() or word[:1].isupper())):
        return -0.06
    if word.startswith(('-', "'")):
        word = word[1:]
        n = len(word)
    if not word.isalpha():
        return 0.01
    if not word.isascii():
        return min(0.6, 0.28 + 0.05 * n)
    if word.isupper():
        return 0.07 if n <= 3 else 0.35
    if word.istitle():
        return min(0.65, max(0.0, 0.15 * (n - 2)))
    if previous.startswith((' ', '-')):
        if word in SHORT_FUNCTION_WORDS:
            return 0.61
        if n <= 3:
            return max(0.02, 0.26 * (n - 1))
        return min(0.90, 0.70 + 0.025 * (n - 4))
    strength = min(0.80, 0.14 + 0.08 * n)
    if word in WORD_SUFFIXES:
        strength += 0.2
    return min(0.88, strength)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    strength = word_strength(previous)
    if token == '.':
        value = -strength
    elif token == '。':
        if any('\u3040' <= ch <= '\u30ff' for ch in previous):
            value = -0.41
        elif any('\u3400' <= ch <= '\u9fff' for ch in previous):
            value = -0.76 if len(previous.strip()) >= 2 else -0.62
        else:
            value = -0.49
    elif token == ').':
        value = -0.12 - 0.13 * strength
    elif token in ('.\n', '.\n\n'):
        value = 0.11 - 0.19 * strength
    elif token in (').\n', ').\n\n'):
        value = 0.16
    elif token in ('."', '.”'):
        value = -0.12
    elif token in ('...', '…'):
        value = 0.13
    elif token == '，':
        value = 0.07
    elif token in (',', ':'):
        value = 0.015
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""Detect text cues for web-page furniture: headings, fields, and actions."""
import re

READS = ()

SECTIONS = {
    "answer", "history", "introduction", "reference", "references", "citations",
    "publications", "related", "copyright", "location", "source",
}
PROFILE_FIELDS = {
    "tags", "kudos", "joined", "posts", "status", "offline", "online",
    "moderator", "anonymous", "editors", "warranty",
}
ACTION_WORDS = {"click", "clicking", "commenting", "recommend", "messaging"}
LABELS = SECTIONS | PROFILE_FIELDS
LAST_WORD = re.compile(r"[A-Za-z]+$")
AGE_PHRASE = re.compile(r"\b\d+\s+year\s+old$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old = ""
    else:
        old = carry[1]
    text = old + token
    tail = text.rstrip()
    offset = len(text) - len(tail)
    value = 0.0
    match = LAST_WORD.search(tail)
    word = match.group().lower() if match else ""
    word_start = offset + match.start() if match else len(text)
    fresh_word = bool(match and word_start + len(word) > len(old))

    # A label is useful mainly at the start of a line, often after a newline.
    if fresh_word and word in LABELS:
        line = text[:word_start].rsplit("\n", 1)[-1]
        if not line.strip(" \t#>*-"):
            value = 0.9 if word in PROFILE_FIELDS else 0.6
        elif word == "publications" and line.strip().lower() == "recent":
            value = 0.6
        elif word == "copyright" and line.rstrip().endswith("*"):
            value = 0.6

    # Calls to action can be embedded in prose rather than set as a heading.
    if value == 0.0 and fresh_word and word in ACTION_WORDS:
        value = 0.45

    # A few recognizable inline labels and the common heading markers.
    if value == 0.0:
        recent = tail[max(0, len(old) - 48):].lower()
        if (
            fresh_word
            and word == "anonymous"
            and re.search(r"asked by\s+anonymous$", recent)
        ):
            value = 0.9
        elif fresh_word and word == "old" and AGE_PHRASE.search(recent):
            value = 0.55
        elif (
            fresh_word
            and word == "database"
            and re.search(r"\bcreate\s+database$", recent)
        ):
            value = 0.45
        else:
            marker = re.search(r"#{1,6}$|•$", tail)
            if marker:
                start = offset + marker.start()
                line = text[:start].rsplit("\n", 1)[-1]
                fresh = start + len(marker.group()) > len(old)
                if fresh and not line.strip(" \t#"):
                    value = 0.35 if marker.group().startswith("#") else 0.12

    return (doc, text[-160:]), float(value)

"""Respond to explicit problems, exceptions, and things out of the ordinary.

The component is usually quiet, but it tends to rise on words naming errors,
faults, suspicion, harm, or unusual events. This small word-class predictor
captures those clear lexical cues; it does not model the component's weaker
context-dependent background activity.
"""

READS = ()

ERRORS = {
    "error", "exception", "fault", "bug", "syntaxerror", "keyerror",
    "valueerror", "logerror", "traceback", "incident", "defect",
}
UNUSUAL = {
    "strange", "weird", "unusual", "exceptional", "odd", "peculiar",
    "monster", "ghost",
}
TROUBLE = {
    "crime", "accusation", "suspect", "suspicious", "suspected",
    "faulty", "scream", "carcass", "complaint", "complaints",
    "throw", "throws", "foreign",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if any(term in word for term in ERRORS):
        return None, 1.0
    if any(term in word for term in UNUSUAL):
        return None, 0.75
    if any(term in word for term in TROUBLE):
        return None, 0.6
    return None, 0.0

programs.sol:
"""Predict closing pulses for short bracketed or quoted spans.

Remember opening marks within each document. Their closing pulses decay with
span length. Identifier-attached parentheses decay faster; short citation-like
square brackets ending in digits get a boost. Word-like quotations are stronger
than quoted symbols. Standalone marks usually matter most: leading spaces on
these marks and most merged punctuation weaken pulses. Ordinary text gets zero.
"""
from math import exp
import re

READS = ()
PAIRS = dict(zip(')]}）】》」』”’»', '([{（【《「『“‘«'))
OPENERS = frozenset(PAIRS.values())
QUOTES = frozenset(('"', "'", '`'))
# Elided French articles/pronouns use apostrophes, not paired quotes.
FRENCH_PREFIXES = frozenset(('l', 'd', 'j', 'm', 't', 'c', 's', 'n', 'qu'))

PUNCTUATION = frozenset('()[]{}\\^$.,;!?+-%*&_\n\r\t' + ''.join(QUOTES))
SYMBOLS = frozenset('+%*&;')
# Baseline, short-span boost, and length-decay rate for delimiter families.
PULSES = {
    ']': (0.25, 0.52, 0.12), '}': (0.08, 0.28, 0.16),
    '`': (-0.23, 0.57, 0.11),
    '"': (-0.12, 0.78, 0.15), "'": (-0.09, 0.585, 0.15),
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, {}, {}, 0, '')
    # Opening records hold token position, character position, and a context flag.
    _, brackets, quotes, characters, previous = carry
    token = prefix.token_strings[-1]
    position = prefix.position
    value = 0.0
    for q, opening in list(quotes.items()):
        if position == opening[0] + 1 and token and not token[0].isalnum():
            quotes[q] = (opening[0], opening[1], 0.25 * opening[2])
    for j, ch in enumerate(token):
        match = None
        if ch in OPENERS:
            before = previous + token[:j]
            word = re.search(r'[A-Za-z_][A-Za-z_0-9]*$', before)
            call = ch == '(' and word is not None and len(word[0]) > 1
            citation = ch == '[' and bool(j and token[:j].isspace())
            citation = citation and previous.rstrip()[-1:].isalnum()
            opening = (position, characters + j, call or citation)
            brackets.setdefault(ch, []).append(opening)
        elif ch in PAIRS:
            stack = brackets.get(PAIRS[ch], [])
            if stack:
                match = stack.pop()
        elif ch in QUOTES:
            before = (token[:j] or previous)[-1:]
            after = token[j + 1:j + 2]
            apostrophe = ch == "'" and (
                before.isalpha() and after.isalpha()
                or token == "'" and previous.strip().lower() in FRENCH_PREFIXES
            )
            if not apostrophe:
                spaced = bool(j and token[:j].isspace())
                if ch in quotes and not spaced:
                    match = quotes.pop(ch)
                else:
                    cjk = '\u3400' <= before <= '\u9fff'
                    natural = spaced or before in ('(', '`') or cjk
                    quality = 1.0 if natural else 0.0
                    in_call = brackets.get('(') and brackets['('][-1][2]
                    if before == '(' and in_call:
                        quality *= 0.25
                    if after and not after.isalnum():
                        quality *= 0.25
                    quotes[ch] = (position, characters + j, quality)
        else:
            continue

        if ch not in PAIRS and ch not in QUOTES:
            continue
        # The component is sensitive to how punctuation is tokenized.
        core = token.strip(' ')
        simple = core == ch
        suffix = token[j + 1:]
        if not simple and ch in QUOTES:
            continue
        if not simple and not all(c in PUNCTUATION for c in core):
            continue
        if not simple and any(c in QUOTES or c in PAIRS for c in suffix):
            continue
        gap = position - match[0] if match else -1
        length = max(0, gap - 2)
        if ch == ')':
            span = characters + j - match[1] if match else 1000
            if not match:
                value = 0.10
            elif match[2]:
                value = 0.13 + 0.77 * exp(-0.08 * span)
            else:
                value = 0.13 + 0.85 * exp(-0.027 * span - 0.05 * length)
        elif not match or ch in QUOTES and not match[2]:
            value = 0.28 if ch == ']' else 0.04 if ch == '}' else 0.05
            if ch in QUOTES:
                value = 0.02
        else:
            floor, boost, rate = PULSES.get(ch, (-0.02, 0.77, 0.12))
            value = floor + boost * exp(-rate * length)
            if ch in QUOTES:
                value *= match[2]
        if ch == ']' and match and match[2] and previous.isdigit() and gap <= 4:
            value += 0.25
        if not simple:
            empty = match and match[0] == position and token[j-1:j] == PAIRS.get(ch)
            if empty:
                value = 0.0
            elif suffix and any(c in OPENERS for c in suffix):
                value *= 0.22
            elif suffix:
                # Sentence punctuation largely cancels the closing pulse.
                value = 0.4 * value - 0.22 if ch == ')' else 0.0
            elif ch == ')' and core[:core.rfind(ch)].lstrip('(') in SYMBOLS:
                value = max(value, 0.65)
            elif ch == ')' and any(c in '.!?' for c in core[:-1]):
                value = max(0.4 * value, 0.30)
            else:
                value *= 0.22
        if token.startswith(' ') and simple:
            value *= 0.55
    return (document, brackets, quotes, characters + len(token), token), float(value)

programs.luna:
"""Recognize closing brackets and quotes inside paired double-quoted text.

The component has its clearest positive response to ) and ]; paired ASCII
quotes are a weaker cue, and opening quote marks are less predictive.
"""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    inside_quote = carry[1] if carry is not None and carry[0] == document else False
    token = prefix.token_strings[-1]
    mark = token.lstrip()

    if len(mark) == 1 and unicodedata.category(mark) in ("Pe", "Pf"):
        value = {
            ")": 0.62,
            "]": 0.60,
            "}": 0.27,
            "）": 0.38,
            "】": 0.35,
            "》": 0.50,
            "”": 0.52,
        }.get(mark, 0.35)
        if token != mark:
            value *= 0.5
    elif token == '"':
        value = 0.37 if inside_quote else 0.08
    elif token == "'":
        value = 0.09
    elif token == "`":
        value = 0.13
    else:
        value = 0.0

    for character in token:
        if character == '"':
            inside_quote = not inside_quote
    return (document, inside_quote), float(value)

programs.sol:
"""Approximate negative activations on cybersecurity and web vocabulary.

Word classes give a baseline and an extra negative response when an explicit
cyber term occurred in the previous 64 tokens. Document-initial responses
double, capped at -3; "cyber attack"-type phrases are also strengthened.
"Instance(s) of" and "peer-reviewed" are independent phrase responses.
Most small, token-specific activations are deliberately omitted. A broader
version adds more software brands, harm/protection terms, and translations.
"""
import string

READS = ()

MALICIOUS_CODE = ('malicious', 'malware', 'spyware', 'ransomware',
                  'phishing', 'rootkit', 'botnet')
WEB_SOFTWARE = {
    'microsoft', 'icrosoft', 'norton', 'cisco', 'vmware', 'apache',
    'wordpress', 'bukkit', 'chrome', 'firefox', 'mozilla', 'canary',
    'beautifulsoup', 'urllib', 'vpn', 'ssl', 'dns', 'smtp', 'iptables',
}
WEB_USE = {'cookie', 'cookies', 'browser', 'browsers', 'hosting', 'seo',
           'privacy', 'secure', 'securely', 'confidentiality', 'tor'}
NETWORKING = {'website', 'websites', 'server', 'servers', 'network',
              'networks', 'domain', 'domains', 'email', 'mail', 'address',
              'password', 'passwords', 'certificate', 'encryption'}
CYBER_QUALIFIERS = {'cyber', 'malicious', 'malware', 'phishing',
                    'spyware', 'ransomware'}


def response(token, previous):
    # Return baseline, contextual strengthening, and whether this is a cyber cue.
    word = token.strip().strip(string.punctuation).lower()
    if word.startswith(MALICIOUS_CODE):
        return -2.3, 0.25, True
    if word == 'ware' and previous.lower().endswith(('mal', 'spy', 'ransom')):
        return -2.3, 0.25, True
    if any(s in token for s in ('恶意', '惡意', '悪意', '漏洞')):
        return -2.3, 0.25, True
    if word.startswith(('firewall', 'cybersecurity', 'antivirus', 'cloudflare')):
        return -1.55, 0.0, True
    if word.startswith(('vulnerabil', 'exploit')):
        return -1.2, 0.35, True
    if word.startswith('attacker') or word in {'hacker', 'hackers'}:
        return -1.4, 0.3, True
    if word.startswith(('obfuscat', 'spam')):
        return -1.05, 0.0, True
    if word.startswith('cyber'):
        return -0.75, 0.0, True
    if word in {'security', 'ecurity', 'urity'}:
        return -0.7, 0.4, False
    if word.startswith(('attack', 'threat')):
        return -0.58, 0.65, False
    if word.startswith(('vulnerable', 'suspicious', 'breach', 'compromis')):
        return -0.68, 0.3, False
    if word.startswith(('hack', 'scam', 'fraud', 'criminal', 'terroris')):
        return -0.35, 0.2, False
    if word in WEB_SOFTWARE:
        return -0.57, 0.0, False
    if word in WEB_USE:
        return -0.42, 0.0, False
    if word in NETWORKING:
        return -0.17, 0.0, False
    if any(s in token for s in ('攻击', '攻擊', '篡', '伪造', '悪', '惡', '威胁')):
        return -0.7, 0.0, False
    if any(s in token for s in ('网站', '邮件', '运维', '私服')):
        return -0.42, 0.0, False
    if token in {'安全', '的安全', '安心', 'ご利用', 'を利用して'}:
        return -0.5, 0.0, False
    return -0.002, 0.0, False


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, recent, position = '', 0, 0
    else:
        _, previous, recent, position = carry
    token = prefix.token_strings[-1]
    value, strengthening, cue = response(token, previous)
    if recent:
        value -= strengthening
    word, before = token.strip().lower(), previous.strip().lower()
    if before in CYBER_QUALIFIERS and word.startswith(
        ('attack', 'threat', 'security', 'vulnerabil')
    ):
        value = min(value, -2.3)
    if word == 'of' and before in {'instance', 'instances'}:
        value = -0.575 if before == 'instance' else -0.39
    if token == '-reviewed' and before.endswith('peer'):
        value = -0.69
    if position == 0 and value != -0.002:
        value = max(-3.0, 2.0 * value)
    recent = 64 if cue else max(0, recent - 1)
    return (document, token, recent, position + 1), float(value)

"""Approximate a weak, mixed lexical response, not a single semantic detector.

Use visible word endings, return/repetition words, ease words, code literals,
identifier roles, address/file endings, and a few punctuation/format markers.
Most tokens receive almost zero. The preceding token and a short text tail
are retained only to distinguish suffixes and compound or named expressions.
