import re

READS = ()

WORD_ENDINGS = {
    's': -0.028, 'es': -0.017, 'ing': -0.037, 'ed': -0.006,
    'ly': -0.032, 'able': -0.057, 'ible': -0.015,
    'ment': -0.015, 'ness': 0.007, 'ity': -0.016,
    'al': -0.015, 'er': -0.015, 'est': -0.002,
    'ful': -0.017, 'less': -0.032, 'ous': 0.007, 'ive': 0.019,
}
ADDRESS_ENDINGS = {
    '.com': -0.047, '.org': -0.099, '.net': -0.015, '.io': -0.040,
}
FILE_ENDINGS = {
    '.js': -0.051, '.py': 0.039, '.sh': 0.061, '.ts': -0.032,
    '.json': -0.028, '.xml': -0.031, '.md': -0.030, '.h': -0.028,
}
SYMBOLS = {
    '@': 0.058, '•': 0.036, '&': -0.031, '#': -0.014,
    '^': -0.017, '`': 0.014, ':': -0.008,
    ':=': -0.070, '==': -0.018, '===': -0.018,
    '</think>': -0.071, '<tool_call>': -0.046,
}
IDENTIFIER_ROLES = frozenset(
    'Error Exception Manager Listener Event Options Result Name Input Output '
    'Metadata Offset Builder Handler Provider Context'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    continued = bool(previous and token and previous[-1].isalpha()
                     and token[0].isalpha())
    value = 0.0001
    if continued:
        value += WORD_ENDINGS.get(token, 0.0)
        if word in IDENTIFIER_ROLES:
            value -= 0.111
    if lower in ('back', 'again', 'once', 'twice'):
        value += 0.080
    if lower in ('ease', 'easy', 'easily'):
        value -= 0.071
    if word in ('true', 'false'):
        value += 0.051
    elif word in ('True', 'False'):
        value += 0.020
    elif lower == 'null':
        value -= 0.038
    if lower == 'license':
        value -= 0.063
        if re.search(r'(Public|Attribution)\s*$', tail):
            value -= 0.112
    value += ADDRESS_ENDINGS.get(word, 0.0)
    value += FILE_ENDINGS.get(word, 0.0)
    value += SYMBOLS.get(word, 0.0)
    if token.startswith('\t') and token.endswith('\n') and not word:
        value -= 0.033
    if any('\u4e00' <= c <= '\u9fff' for c in token):
        value += 0.007
    if any('\uac00' <= c <= '\ud7af' for c in token):
        value -= 0.010
    if any('\u0400' <= c <= '\u04ff' for c in token):
        value -= 0.004
    return (doc, token, (tail + token)[-100:]), float(value)

"""Approximate the strong n/nu-family responses, especially Greek and Arabic.

Greek nu is strongly negative; neighbouring Greek vowels adjust its strength.
Other Greek sonorants and non-Latin letters for n respond less strongly. Arabic
alif-nun connectives have particularly large negative responses. A small set of
conditional/contrastive words also responds. Other tokens default to zero. This captures
large responses, not the many weak, idiosyncratic lexical fluctuations.
State resets at document boundaries. Split-byte characters are recognized only
when the current decoded prefix has completed them.
"""
import unicodedata

READS = ()

# Non-Latin n letters and Mandarin en (恩), including transliterations.
N_LETTERS = {
    'ن': -0.75,
    'น': -0.65,
    'ン': -0.65,
    'ܢ': -0.65,
    'न': -1.15,
    'ন': -1.15,
    'ਨ': -1.15,
    'ந': -1.8,
    'ன': -1.8,
    'న': -1.8,
    'נ': -0.3,
    'ן': -0.3,
    'ん': -0.3,
    'ナ': -0.3,
    'ﾝ': -0.3,
    'н': -0.25,
    '恩': -3.4,
}

# Arabic that/if, because, but, and attached function-word forms.
ARABIC_CONNECTIVES = {
    'وأن': -3.8,
    'وإن': -3.8,
    'فإن': -3.8,
    'لأن': -4.7,
    'بأن': -4.7,
    'لكن': -2.3,
    'ولكن': -2.05,
    'أنه': -1.3,
    'إنه': -1.9,
    'أ': -0.55,
    'وأ': -0.55,
    'أو': -0.55,
}


def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def greek(c):
    return bool(c) and '\u0370' <= c <= '\u03ff' and c.isalpha()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, age = ('', 99) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token[:1].isspace()
    fragment = word == '\ufffd'
    if fragment:
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            word = completed
    letter = plain(word)
    prev = plain(previous.rstrip())
    last = prev[-1:]
    value = 0.0

    if letter == 'ν':
        if fragment:
            value = -1.5
        elif spaced:
            value = -2.1 if age < 8 else -1.1
        elif last in ('α', 'ε', 'η'):
            value = {'α': -2.75, 'ε': -3.1, 'η': -2.9}[last]
            value -= 0.3 if previous[:1].isspace() else 0.0
        elif last == 'ω':
            value = -1.7
        else:
            value = -1.85 if prev.endswith('ου') else -2.2
    elif letter == 'λ':
        if spaced:
            value = -0.65 if age < 8 else -0.06
        elif greek(last):
            value = -1.15 if last in ('α', 'ε', 'η') else -0.5
        else:
            value = -0.05
    elif letter in ('ρ', 'μ'):
        value = -0.34 if letter == 'ρ' else (-0.08 if spaced else -0.18)
    # Weaker cross-script n responses; Persian spelling reduces Arabic nun.
    elif letter in N_LETTERS:
        value = N_LETTERS[letter]
        if word == 'ن':
            if spaced:
                value = -0.25
            elif any(c in previous for c in 'چگ'):
                value = -0.25
            elif any(c in previous for c in 'کی'):
                value = -0.45
    # Alif-nun forms differ sharply at a word boundary versus inside a word.
    elif word in ('أن', 'إن'):
        value = -5.05 if spaced else -4.1
    elif word == 'ان':
        value = -3.8 if spaced else -1.1
    elif word in ('الان', 'الأن', 'الإن'):
        value = -2.5
    elif word in ARABIC_CONNECTIVES:
        value = ARABIC_CONNECTIVES[word]
    elif word in ('ين', 'ني', 'نت', 'الن'):
        value = -0.4
    elif word in ('نا', 'ون', 'من'):
        value = -0.15
    elif word == 'نه' and previous.rstrip().endswith(('أ', 'إ')):
        value = -1.5
    elif word.lower() == 'unless':
        value = -0.4 if spaced and word.islower() else -0.55
    elif word.lower() == 'whenever':
        value = -0.54 if word.islower() else -1.1
    elif word.lower() == 'wenn':
        value = -0.31 if word.islower() else -0.43
    elif word == 'ただ':
        value = -0.76

    age = 0 if any(greek(c) for c in letter) else age + 1
    return (doc, token, age), float(value)

