"""Approximate a mixed, token-local spelling and vocabulary response.

Short 'mi' and related fragments in several scripts receive positive values.
Longer fragments, mi-bearing names and mixing words receive weaker values.
Saving, catching, recovery and exception-handling vocabulary is negative.
Everything else is zero; context and small background responses are omitted.
"""
import string

READS = ()
MI_GLYPHS = {
    'ミ': 4.6, 'み': 2.6, '미': 3.5, '米': 3.0, '密': 1.75,
    '蜜': 1.0, '咪': 1.1, '明': 0.65, '味': 0.7, '秘': 0.6,
    'め': 0.6, 'メ': 0.6,
}
