                     'exception', 'retriev', 'salv')


def response(raw):
    word = raw.strip().strip(string.punctuation)
    w = word.lower()
    if w in {'catch', 'catches', 'catching', 'caught', 'save', 'saves'}:
        return -1.6
    if w in {'saved', 'saving', 'rescued', 'rescuing', 'salvation'}:
        return -1.3
    if w == 'rescue':
        return -2.25
    if w.startswith(RECOVERY_PREFIXES):
        return -0.5
    if w in {'escape', 'escapes', 'escaped', 'escaping', 'cure', 'resume'}:
        return -0.7
    if w.startswith(('assist', 'prevent', 'restore', 'protect')):
        return -0.3
    if word == '救':
        return -6.2
    if word == '拯救':
        return -3.7
    if (len(word) == 2 and '救' in word) or w == 'cứu':
        return -2.0
    if word in {'挽回', '吸引', '化解', '扶持', '助', '援', '扶',
                '逃', '保护', '恢复', '保存'}:
        return -0.8
    if word in MI_GLYPHS:
        return MI_GLYPHS[word]
    if w == 'mi':
        if word.isupper():
            return 3.0
        return 2.1 if raw.startswith(' ') else 2.45
    if w == 'ami':
        return 1.8 if raw.startswith(' ') else 3.8
    if w in {'emi', 'imi', 'omi', 'umi', 'ами', 'ми'}:
        return 1.9
    if w == 'ими':
        return 1.0
    if w == 'mixed':
        return 1.65
    if w in {'mix', 'mixes', 'mixing', 'mixture', 'mixtures', '混', '混合'}:
        return 0.9
    if word == '小米':
        return 2.6
    if w in MI_NAMES or w in {'mí', 'mı', 'omy', 'emy', 'amy', 'omics'}:
        return 0.8
    if w.startswith(('mi', 'ми')):
        if w in {'min', 'мин'}:
            return 0.2
        if len(w) == 3 or w in {'mini', 'mission', 'missions'}:
            return 0.9
        return 0.2
    if len(w) == 4 and w[0] in 'aeiou' and w[1:3] == 'mi':
        return 0.1 if w in {'emit', 'omit', 'imin'} else 1.0
    if w.endswith(('mi', 'ми')):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    value = response(raw)
    if value < 0 and raw.startswith(('.', '}', '-')):
        value *= 0.6
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2044: a "mi" detector with a rescue-word suppressor.

Reads only the current token (its text, lowercased and stripped of spaces) and predicts how
strongly the component fires on it:
  * the bare syllable "mi" in any script (Latin mi, katakana ミ, hiragana み, hangul 미,
    Cyrillic ми, Chinese 米) and "-mi" endings such as ami, umi, emi: about +2.5;
  * short fragments and words that start with "mi" (mit, mix, mid, mis, mic, mini, Miller...):
    about +1.0;
  * other short tokens containing "mi" or "ми": a weak +0.3;
  * rescue / save / catch / escape words (save, catch, rescued, recovery, 救, 拯救): negative,
    about -1.2 (救 and 拯救 are the strongest, about -5);
  * weaker, related "get back / get out / help" words: about -0.25.
Everything else is 0. It has no memory across tokens.
"""

SYLLABLE_MI = {
    "mi", "ミ", "み", "미", "米", "ми",
    "ami", "umi", "emi", "omi", "imi", "ами", "ими", "ями",
}
MI_FRAGMENT = {
    "mit", "mis", "mid", "mix", "mixed", "mixture", "mixing", "mic", "mil", "mir", "mini",
    "mission", "miller", "michigan", "mike", "amin", "omic", "emy", "emia",
    "密", "明", "味", "混", "蜜", "мир",
}
RESCUE_CJK = {"救", "拯救", "救人"}
RESCUE_CORE = {
    "save", "saves", "saved", "saving", "savings", "catch", "catches", "caught", "catching",
    "rescue", "rescued", "escape", "escaped", "recovery", "recover", "capture", "captured",
    "salvation", "cứu",
}
RESCUE_WEAK = {
    "resume", "exception", "discover", "detect", "overcome", "cure", "restore", "alleviate",
    "thwart", "trap", "hook", "lure", "help", "aid", "assist", "助", "援", "逃", "躲", "脱",
    "摆脱", "减轻", "醒", "挽回", "escaping", "escapes", "recovered", "uncovered",
}

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s in SYLLABLE_MI:
        return None, 2.5
    if s in MI_FRAGMENT:
        return None, 1.0
    if s in RESCUE_CJK:
        return None, -5.0
    if s in RESCUE_CORE:
        return None, -1.2
    if s in RESCUE_WEAK:
        return None, -0.25
    if ("mi" in s or "ми" in s) and len(s) <= 4:
        return None, 0.3
    return None, 0.0

