programs.sol:
"""Predict a mostly lexical response to scripts and scripting languages.

' script' and its joined token pieces are strongest; Python, JavaScript, and
source-file extensions follow. Script-related words and programming tools
have smaller responses. Adjacent text distinguishes exit/status codes,
Python code-fence labels, and Python project paths. The Chinese foot
characters also respond, including their use in the word for script.
Everything else receives zero. State is just the previous token, reset at
 each document boundary.
"""
READS = ()

SCRIPT_WORDS = {
    'scripting': -3.0,
    'transcript': -2.5,
    'subscript': -1.4,
    'screenplay': -1.4,
    'manuscript': -0.7,
    'scripture': -0.7,
    'scriptures': -0.7,
    'transcription': -0.35,
    'cription': -0.35,  # split transcription ending
}
CHINESE_SCRIPT_AND_CODE = {
    '脚': -2.0,  # foot, also starts 脚本 (script)
    '腳': -1.3,  # traditional foot character
    '剧本': -1.8,  # screenplay
    '代码': -0.55,  # source code
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('./_-')
    word = spelling.lower()
    spaced = token[:1].isspace()
    path = token.startswith('/')
    extension = token.startswith('.')

    if word in {'script', 'cript'}:
        value = -4.3 if spaced or path else -5.0
        if spelling == 'Script':
            value -= 0.7
    elif word in {'scripts', 'cripts', 'scripted'}:
        value = -2.85 if path else -3.9
    elif word == 'python':
        value = -2.3 if spaced or token.startswith('_') else -2.6
        if path:
            value = -2.3 if previous.endswith('/workspace') else -3.4
        elif extension:
            value = -3.1
        elif previous.endswith('```'):
            value = -1.9
    elif word == 'thon':  # a split Python ending, also matches other words
        value = -2.1
    elif word == 'py':
        value = -2.0 if extension or token.startswith('_') else -1.0
    elif word == 'js':
        value = -1.45 if path or spelling == 'Js' else -1.9
    elif word in {'javascript', 'avascript', 'typescript'}:
        value = -1.65 if spelling == 'javascript' else -2.4
    elif word in {'php', 'ruby', 'uby'}:
        value = -0.65
    elif word == 'jsx':
        value = -1.1 if spelling == 'jsx' and not spaced else -0.3
    elif word == 'ts':
        value = -0.6 if extension else (-0.45 if path else -0.06)
    elif word == 'sh':
        value = -0.33 if extension else 0.0
    elif word == 'java':
        value = -0.07 if spaced and spelling == 'java' else -0.3
    elif word == 'code':
        value = -0.7 if token.startswith(' c') else -0.25
        if previous.strip().lower() == 'exit':
            value = -1.22
        elif previous.strip().lower() == 'status':
            value = 0.0
    elif word in {'npm', 'interpreter', 'virus'}:
        value = -0.6
    elif word in {'pylint', 'executable', 'utable', 'perl'}:
        value = -0.5
    elif word in {'pip', 'sql', 'prototype'}:
        value = -0.3
    elif word == 'torch':
        value = -0.8 if spelling == 'Torch' else -0.3
    elif token == '/LICENSE':
        value = -0.65
    elif word == '本' and previous.endswith(('脚', '腳')):
        value = -4.4
    else:
        value = SCRIPT_WORDS.get(word, CHINESE_SCRIPT_AND_CODE.get(word, 0.0))
    return (doc, token), value

programs.haiku:
"""Layer-0 MLP component 2045: a "programming-language and scripting words" detector.

Its job is to push the residual stream negative on tokens that name a script, a
programming language, or a file extension for one. Strongest on "script", "Script",
"scripts" (about -4.3). Then "Python" and "/python" (-2.5 to -3.0), ".py" (-2.0),
"JavaScript", "JS" and ".js" (about -1.9), and words ending in "script" such as
"transcript" and "typescript" (-2.3). Weaker (about -0.6) on ".php", "npm", "code",
"interpreter", "virus", ".ts" and "ruby". A bare "py" is about -1.0. Everything else
gets 0. Each activation depends only on the token just read, so the program keeps no state.
"""

READS = ()

SCRIPT_WORDS = {"script", "scripts", "scripted", "scripting", "cript", "scriptable"}
PYTHON_WORDS = {"python", "thon", "pythonic"}
PY_EXT = {"py", "pyc"}
JS_WORDS = {"js", "jsx", "javascript"}
WEAK_WORDS = {"php", "npm", "ruby", "uby", "code", "virus", "interpreter"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip("./_-").lower()
    if word in SCRIPT_WORDS:
        value = -4.3
    elif word in PYTHON_WORDS or word.endswith("python"):
        value = -3.0 if raw[:1] in "./" else -2.5
    elif raw.startswith(".") and word in PY_EXT:  # ".py" (bare "py" is weaker)
        value = -2.0
    elif word in PY_EXT:
        value = -1.0
    elif word in JS_WORDS:
        value = -1.9
    elif word.endswith("script") and word != "manuscript":  # transcript, typescript
        value = -2.3
    elif word in WEAK_WORDS or raw in (".ts", "/ts"):
        value = -0.6
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Recognize programming-language names and source-file markers, with a
smaller negative response to words used around code and executables."""
READS = ()

LANGUAGES = {"js", "javascript", "python", "php", "ruby", "torch", "jsx"}
SOURCE_ENDINGS = (".js", ".py", ".ts")
CODE_WORDS = {"code", "virus", "executable"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    lower = token.lower()

    if word in LANGUAGES:
        return None, -1.7
    if lower.endswith("/python"):
        return None, -3.0
    if lower.endswith(SOURCE_ENDINGS):
        return None, -1.8
    if word == "prototype":
        return None, -0.7
    if word in CODE_WORDS:
        return None, -0.6
    return None, 0.0

programs.sol:
"""A modest lexical approximation to a weak, diffuse component.

Totality and apprehension words tend negative; evidence, comparison, and
location words tend positive. Add small spelling corrections. Most
token-specific and contextual variation remains unexplained.
"""

READS = ()


def words(text):
    return frozenset(text.split())


def verb_forms(roots):
    result = set()
    for root in roots.split():
        stem = root[:-1] if root.endswith("e") else root
        result.update((root, root + ("es" if root.endswith("ch") else "s"),
                       stem + "ing", root + ("d" if root.endswith("e") else "ed")))
    return result


EVIDENCE = verb_forms("show record suggest indicate demonstrate reveal reflect") | {"shown"}
APPREHENSION = verb_forms("notice recognize realize remember trust sense touch")
APPREHENSION |= words("understand understands understood understanding forget forgets "
                     "forgot forgotten forgetting feel feels felt feeling feelings")
RULES = (
    (-0.0854, words("everybody everyone everything nobody")),
    (-0.0350, words("completely entirely totally fully wholly altogether perfectly")),
    (-0.0664, words("completely entirely")),
    (-0.0301, words("some few many several numerous")),
    (0.0294, words("although despite else however instead nevertheless "
                   "nonetheless otherwise whereas while")),
    (0.0406, words("such than")),
    (-0.0420, words("like alike")),
    (0.0307, words("being been")),
    (0.0496, words("per")),
    (0.0485, words("place places location locations located")),
    (0.0409, EVIDENCE),
    (-0.0506, APPREHENSION),
)
MARKERS = {"<tool_response>": -0.1093, "<|im_end|>": 0.0253}
SUFFIXES = words("ed ing ist ness ism ic")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0001 + MARKERS.get(token, 0.0)
    if word.isascii() and word.isalpha():
        for estimate, vocabulary in RULES:
            if word in vocabulary:
                value += estimate
        if word.endswith("ly"):
            value -= 0.0210
        if len(word) > 10:
            value -= 0.0091
        if not token.startswith(" ") and word in SUFFIXES:
            value -= 0.0271
    if word and all(c in "⁰¹²³⁴⁵⁶⁷⁸⁹" for c in word):
        value += 0.0448
    return None, float(value)
